"use strict";
const INST={
 ir5:["Insulation resistance tester (megger), 5 kV","Applies a steady DC voltage (500 V – 5 kV) and reads leakage as MΩ/GΩ. Motorised or electronic; 1-min, DAR and PI readings."],
 ir1:["Insulation tester, 500 V / 1 kV","For LV windings, control wiring, meters and LT cables."],
 ttr:["Turns ratio tester (TTR)","Measures the voltage ratio phase by phase at every tap, plus phase angle and excitation current."],
 wrm:["Winding resistance meter","Pushes a steady DC current (1–25 A) and measures milliohms with 4-wire (Kelvin) leads."],
 dlro:["Micro-ohm meter (DLRO / CRM), 100–200 A","Contact resistance of breaker poles, isolators, busbar joints and jumpers, in µΩ."],
 bta:["Breaker timing / operation analyser","Records close and open times of each pole, pole discrepancy, coil currents and travel."],
 cta:["CT analyser or knee-point kit (variac + voltmeter + ammeter)","Ratio, polarity, knee point, excitation curve, winding resistance and burden of CTs."],
 rtk:["Relay test kit (secondary injection set)","3-phase current and voltage source with a timer; injects into relays to check pickup, timing and logic."],
 pis:["Primary injection set","Low-voltage, high-current source (hundreds to thousands of amps) passed through CT primaries."],
 tand:["Tan delta & capacitance test set","Measures dielectric loss (tan δ / power factor) of windings, bushings and CTs, usually at 10 kV."],
 sfra:["SFRA analyser","Sweep frequency response of transformer windings; compared with the factory fingerprint to find core/winding movement."],
 bdv:["Oil BDV test set (0–80/100 kV)","Breakdown voltage of transformer oil in a standard cell with a 2.5 mm gap."],
 et:["Earth resistance tester (3/4-pole) + clamp-on tester","Fall-of-potential earth resistance, Wenner soil resistivity, and clamp readings on in-service earths."],
 rss:["Portable reference standard meter (class 0.05 / 0.1 / 0.2)","Site accuracy test of energy meters; has its own voltage leads and clamp CTs, and a pulse scanner."],
 bench:["Meter test bench","Lab bench with stable source and reference meter to test many meters at set loads and power factors."],
 mm:["Multimeter, tong tester (clamp meter), phase-sequence meter","Everyday checks of voltage, current, continuity and phase rotation."],
 hyd:["Hydrometer, cell voltmeter, thermometer","Battery specific gravity, individual cell voltage and electrolyte temperature."],
 bdt:["Battery discharge load bank","Discharges the bank at a set current to prove capacity (C10 test)."],
 cmri:["CMRI / MRI, optical probe, laptop with meter software","Downloads meter data, events, load survey and tamper logs."],
 tc:["Thermal imaging camera","Finds hot joints, clamps, bushings and fuse holders while on load."],
 hv:["HV test set (AC / VLF / DC)","Withstand tests on cables, switchgear and vacuum bottles."],
 tdr:["Cable fault locator (TDR, surge generator, pin-pointer)","Finds the distance and exact spot of a cable fault."],
 lac:["LA leakage current tester","Total and resistive (3rd harmonic) leakage current of metal-oxide surge arresters."],
 pt:["Discharge rod, earthing sets, PPE, live-line tester","Safety kit; no test starts without it."]
};
const GROUPS=["Start here","Transformers","Switchgear","CTs and PTs","Surge and earthing","Protection","DC and control","Cables and capacitors","Energy meters","Commissioning and upkeep"];
const S=[
/* ===================== START HERE ===================== */
{id:"about",g:"Start here",t:"What T&C does",
 lead:"Testing & Commissioning (T&C) proves that equipment is healthy, correctly wired and correctly protected before it is charged, and checks it again when it trips, fails or is due for maintenance. If O&M keeps the network running, T&C is the doctor who certifies it.",
 when:["New substation, bay, PTR, VCB, CT-PT unit or DT before first charging","After repair, overhaul or replacement","After a trip, a failure or an accident","Periodic (preventive) testing","Consumer meter complaints and theft cases"],
 tests:[
  {n:"Pre-commissioning tests",w:"Individual equipment and the whole scheme are tested before charging; T&C signs the clearance.",h:"Run the test list for each item, then scheme checks (every protection trips the right breaker).",p:"Every test within limits and recorded; settings applied as approved."},
  {n:"Protection settings",w:"Relays decide how fast and how selectively a fault is cleared.",h:"Settings are calculated (or received from the planning/protection wing), applied, then proved by injection.",p:"Relays operate within their tolerance; grading between stages holds."},
  {n:"Fault and failure analysis",w:"Every trip or failure has a cause; finding it prevents the next one.",h:"Read relay flags and events, test the failed equipment, inspect, report.",p:"A written cause and a recommendation (repair, replace, re-set, re-earth)."},
  {n:"Meter testing (MRT)",w:"Revenue depends on accurate meters and honest wiring.",h:"Lab testing of new and complaint meters, site testing of CT/PT-operated and HT meters, tamper investigation.",p:"Errors within the meter's accuracy class; seals and wiring in order."},
  {n:"Condition monitoring",w:"Catches defects before they fail in service.",h:"Oil tests, thermography, tan delta, battery checks, earth resistance, trend comparison.",p:"Trends stable; anything rising is planned for maintenance."}],
 proc:[{h:"How a typical T&C job flows",s:[
  "Request arrives (new work from Projects/contractor, failure from O&M, complaint from Revenue).",
  "Collect drawings: SLD, schematic/wiring diagrams, equipment test certificates, approved relay settings.",
  "Plan the shutdown and permit-to-work with O&M; list the tests and instruments (with valid calibration).",
  "Isolate, prove dead, earth, then test. Record readings on the format as you go, not from memory later.",
  "Compare with factory values, the standard and earlier readings (trend matters as much as the limit).",
  "Clear for charging, or write the defect with a clear recommendation. Sign, date, and hand over a copy."]}],
 notes:[["tip","Three numbers decide a result: the reading, the limit, and the last reading. A value inside the limit but much worse than last time is still a warning."],
  ["tip","APDCL's own T&C manuals, circulars, approved settings and the maker's manual override the typical values in this handbook. Use these pages to understand the work, then follow the local document."],
  ["trap","Never test with an instrument whose calibration has lapsed; the report can be challenged, especially in metering and accident cases."]],
 rec:["Equipment name, location, make, serial number, rating","Date, ambient temperature, oil/winding temperature","Instrument with serial number and calibration due date","Readings, limit, remark (OK / not OK)","Names and signatures of the tester, O&M in-charge and contractor"],
 quiz:[
  {q:"A DT's IR is 700 MΩ (limit 400 MΩ). Last year it read 3,000 MΩ. What do you do?",o:["Pass it; it's above the limit","Pass it but investigate the big drop (moisture, oil) before trusting it","Reject the transformer","Repeat with a 500 V tester"],a:1,e:"Inside the limit but the trend has fallen sharply. Check oil BDV/moisture, terminals and temperature correction."},
  {q:"Which document sets the relay settings you apply?",o:["The relay's default settings","Whatever the old relay had","The approved settings from the protection/planning authority","The contractor's choice"],a:2,e:"Settings come from an approved calculation and are proved by injection."},
  {q:"What must happen before you touch any HV equipment for testing?",o:["Switch off the breaker only","Isolate, prove dead, discharge and earth under a permit","Open the DO fuse","Ask a lineman to hold the earth rod"],a:1,e:"Isolation, proving dead, discharge and earthing under a permit-to-work come first, every time."}]},

{id:"safety",g:"Start here",t:"Safety, permits and isolation",
 lead:"Most T&C accidents come from back-feed, a forgotten earth, capacitive charge left after an IR or HV test, or an open-circuited CT. A strict routine prevents all four.",
 when:["Before every test on HV or LV equipment","While working in a live substation","After every IR, tan delta or HV test (discharge)"],
 tests:[
  {n:"Permit-to-work (PTW)",w:"Written proof that the equipment is isolated and earthed and who may work on it.",h:"Issued by the authorised O&M person; names the limits of the work zone and the earths applied.",p:"PTW in hand, limits understood, all workers briefed."},
  {n:"Isolation and lock-out",w:"Removes every possible source, including back-feed from LT and parallel lines.",h:"Open breaker, then isolators/AB switch; rack out VCB trucks; remove fuses; lock and tag.",p:"Visible break on every source side."},
  {n:"Prove dead",w:"A switch may have failed or the wrong one may have been opened.",h:"Use a tested live-line indicator (test it on a known live point before and after).",p:"No voltage on any phase."},
  {n:"Earthing",w:"Protects against accidental charging, induction from nearby lines and stored charge.",h:"Apply portable earths on both sides of the work point, earth end first, then line end with an insulated rod.",p:"Earths on every source side, recorded on the PTW."},
  {n:"Discharge after tests",w:"Windings, cables and capacitors store charge after an IR or HV test and can kill.",h:"Discharge through the instrument and then a discharge rod for at least as long as the test lasted (cables: much longer).",p:"Discharged and earthed before touching leads."}],
 proc:[{h:"Golden rules on the day",s:[
  "Brief the team: what is live, what is dead, where the earths are.",
  "Test your live-line indicator on a live point before proving dead.",
  "Never open a loaded CT secondary; short it at the test terminal block first.",
  "Keep HV test areas barricaded; one person controls the test voltage.",
  "Remove all test earths and leads, then return the PTW before charging. Count your earths."]}],
 notes:[["safe","An open CT secondary on load can produce thousands of volts and burn the CT. Always short the secondary (at the TTB or shorting links) before removing a meter or relay."],
  ["safe","After a 5 kV IR test on a long cable or big transformer, discharge for at least 4× the test time."],
  ["trap","LT back-feed: a DG set, inverter or solar rooftop on the LT side can energise a 'dead' DT through its LT bushings. Open the LT side too."],
  ["safe","Battery rooms collect hydrogen. No flames or sparks; ventilate; wear goggles and apron when handling electrolyte."]],
 rec:["PTW number and issuing officer","Earths applied (number, location) and removed","Time of return of PTW"],
 quiz:[
  {q:"Which comes first?",o:["Apply earth","Prove dead","Start the IR test","Open the isolator"],a:3,e:"Isolate first, then prove dead, then earth."},
  {q:"Why discharge a winding after an IR test?",o:["To reset the megger","Stored capacitive charge can give a dangerous shock","To dry the winding","It isn't needed below 5 kV"],a:1,e:"Windings and cables behave like capacitors and keep the test voltage."},
  {q:"You must remove an energy meter fed by a CT on load. First step?",o:["Disconnect the meter quickly","Short the CT secondary at the test terminal block","Open the PT fuses","Earth the meter body"],a:1,e:"Short the CT secondary before breaking the meter's current circuit."}]},

{id:"kit",g:"Start here",t:"The T&C instrument kit",
 lead:"Know what each instrument measures and its limits. Most tests are simple once you know the instrument; most mistakes come from wrong connections or reading the wrong range.",
 when:["Planning any job","Checking calibration validity (usually yearly, traceable to an NABL lab)"],
 kitAll:true,
 tests:[
  {n:"Calibration",w:"An uncalibrated instrument makes every reading questionable.",h:"Keep the certificate and due date with the instrument; check the leads too.",p:"Calibration in date; zero/self-test OK before use."},
  {n:"Leads and connections",w:"Most wrong readings are lead problems.",h:"Check continuity of leads, clean clips, use Kelvin (4-wire) leads for low resistance.",p:"Lead resistance known and small; no broken strands."}],
 notes:[["tip","Low resistance (µΩ, mΩ) always needs 4-wire measurement: current leads outside, potential leads inside, so lead and clip resistance don't count."],["tip","Record the instrument's serial number in every report."]],
 rec:["Instrument register: serial, calibration date, due date, lab"],
 quiz:[
  {q:"Which instrument checks a VCB's contact resistance?",o:["Megger","Micro-ohm meter (DLRO)","TTR","Tong tester"],a:1,e:"A DLRO pushes 100–200 A DC and reads µΩ."},
  {q:"Which instrument finds a hot joint on load?",o:["Thermal imaging camera","Earth tester","BDV kit","Hydrometer"],a:0,e:"Thermography is done on load."},
  {q:"Why use 4-wire (Kelvin) leads for winding resistance?",o:["They are safer","Lead and contact resistance are excluded from the reading","They give higher current","They are required by law"],a:1,e:"The voltage is measured right at the terminals."}]},

{id:"ir",g:"Start here",t:"Insulation resistance: IR, DAR and PI",
 lead:"The IR test is the most common test in T&C. A DC voltage is applied across insulation and the leakage current is read as resistance. The value, how it rises with time, and its trend tell you about moisture, dirt and damage.",
 when:["Every piece of HV and LV equipment before charging","After repair, after a fault, and in routine maintenance"],
 kit:["ir5","ir1","pt"],
 tests:[
  {n:"1-minute IR",w:"Overall health of insulation.",h:"Apply the test voltage for 60 s and read. Use 5 kV for 11/33 kV windings and cables, 2.5 kV or 1 kV for lower, 500 V for LT and control wiring.",p:"Typical minimum at 30 °C (CBIP guidance for transformers): 33 kV 500 MΩ, 11 kV 400 MΩ, LT windings tens to hundreds of MΩ. Healthy new equipment reads far higher."},
  {n:"DAR (60 s / 15 s)",w:"Quick check of moisture.",h:"Read at 15 s and 60 s, divide.",p:"≥ 1.3 acceptable; below 1.25 suspect moisture."},
  {n:"PI (10 min / 1 min)",w:"Best indicator of moisture and contamination in transformers.",h:"Read at 1 min and 10 min, divide.",p:"≥ 1.5 acceptable, ≥ 2 good, below 1.1 poor. Very high IR (GΩ range) may give PI near 1 and still be fine."}],
 proc:[{h:"IR test on equipment",fig:"ir",s:[
  "Isolate, prove dead, earth; then remove earths only from the part under test.",
  "Clean bushings and terminals; disconnect connected equipment (LAs, PTs, cables) that would load the test.",
  "Short together all terminals of the winding/phase under test; earth all others.",
  "Connect Line (–) to the part under test and Earth (+) to the tank/frame. Use Guard to bypass surface leakage on dirty bushings.",
  "Apply the voltage; read at 15 s, 60 s and 10 min. Note winding/oil temperature.",
  "Discharge through the tester, then earth with a discharge rod before touching."]}],
 notes:[["tip","IR roughly halves for every 10 °C rise. Correct readings to a common temperature before comparing (e.g., to 30 °C or 20 °C)."],
  ["trap","Humidity and dirty bushings give low readings that are not real faults. Clean, dry and use the Guard terminal before condemning equipment."],
  ["trap","Forgetting to remove LAs or PTs from a transformer's terminals makes the IR look bad."]],
 rec:["Test voltage, readings at 15 s / 60 s / 10 min, temperature, DAR, PI"],
 quiz:[
  {q:"IR at 40 °C is 300 MΩ. Roughly what is it at 30 °C?",o:["150 MΩ","300 MΩ","600 MΩ","3,000 MΩ"],a:2,e:"IR roughly doubles for each 10 °C fall."},
  {q:"PI is the ratio of…",o:["60 s / 15 s","10 min / 1 min","1 min / 10 min","5 kV / 1 kV readings"],a:1,e:"Polarisation index = IR(10 min) / IR(1 min)."},
  {q:"What is the Guard terminal for?",o:["Earthing the tank","Bypassing surface leakage so only volume insulation is measured","Raising the test voltage","Discharging the winding"],a:1,e:"Guard collects surface leakage current so it isn't counted."}]},

/* ===================== TRANSFORMERS ===================== */
{id:"dtr",g:"Transformers",t:"Distribution transformer (DTR) testing",
 lead:"DTs (16 kVA to 500 kVA, 11 kV/433 V, usually Dyn11) are tested when new, after repair and after failure. The tests are few and fast, and they catch most problems: moisture, a wrong tap or ratio, broken strands, shorted turns and bad oil.",
 when:["New DT before installation/charging","Repaired DT received from the workshop (acceptance)","Failed DT: find the cause before sending for repair","Periodic: oil BDV, IR, earthing, LA and fuse checks"],
 kit:["ir5","ir1","ttr","wrm","bdv","mm","et"],
 tests:[
  {n:"IR (HV–E, LV–E, HV–LV)",w:"Moisture, damaged insulation.",h:"5 kV (or 2.5 kV) on HV, 500 V/1 kV on LV, 1 min each, with the other winding earthed.",p:"HV–E and HV–LV ≥ 400 MΩ at 30 °C (11 kV class); LV–E typically ≥ 100 MΩ for a new DT. Compare with the test certificate."},
  {n:"Ratio at every tap",w:"Correct turns, no shorted turns, tap switch working.",h:"TTR between matching HV and LV phase pairs, or a simple 3-phase 415 V on HV and measure LV.",p:"Within ±0.5% of nameplate ratio (IS 2026); all three phases agree."},
  {n:"Winding resistance",w:"Broken strands, loose joints, bad tap-switch contacts.",h:"DC 4-wire on each HV phase pair and each LV phase–neutral.",p:"Phases agree within about 2%; close to factory value after temperature correction to 75 °C."},
  {n:"Magnetising (no-load) current",w:"Core or turn faults.",h:"Apply 415 V 3-ph to HV with LV open; measure current in each phase.",p:"A few mA; the two outer phases similar, the middle phase lower (3-limb core). A phase much higher than the others points to a shorted turn."},
  {n:"Magnetic balance",w:"Winding/core fault on one limb.",h:"Apply 230 V between one LV phase and neutral; measure the other phases to neutral.",p:"Outer phase applied: most of the voltage appears on the middle phase. Middle applied: shared about equally by the outers. Sum ≈ applied."},
  {n:"Vector group / polarity",w:"A wrong group can't be paralleled and confuses metering.",h:"Join HV R to LV r, apply 415 V 3-ph to HV, measure the set of voltages given in the test kit's chart for Dyn11.",p:"Readings satisfy the Dyn11 relations."},
  {n:"Oil BDV",w:"Moisture and particles in oil.",h:"Standard cell, 2.5 mm gap, 6 breakdowns averaged.",p:"Before charging ≥ 40 kV is a common target for 11 kV DTs; in service, filter or replace below about 30 kV."},
  {n:"Earthing",w:"Lightning and fault safety.",h:"3 separate pits: neutral, body, LA. Measure each with the lead disconnected.",p:"As low as practical; commonly ≤ 5 Ω per pit for DT stations (check your spec)."}],
 proc:[
  {h:"Ratio test with a TTR",fig:"ttr",s:["Isolate and earth, then disconnect HV and LV leads from bushings.","Set the tap to normal (usually 3).","Connect the TTR HV leads to one HV phase pair and the LV leads to the matching LV phase (for Dyn11, HV R–Y pairs with LV r–n per the kit's chart).","Read ratio and excitation current; repeat for all phases and taps.","Calculated ratio for 11000/433 V Dyn11 per phase: 11000 / (433/√3) = 44.0."]},
  {h:"Winding resistance",fig:"wrm",s:["Use 4-wire leads: current leads on the outside, potential leads just inside on the same terminals.","Let the reading settle (inductance). Record winding temperature.","Correct to 75 °C: R75 = Rt × (235 + 75)/(235 + t) for copper (225 instead of 235 for aluminium).","After the test, the meter discharges the winding; wait for it before disconnecting."]},
  {h:"Magnetic balance (simple, no special kit)",fig:"mbal",s:["LT side open, HV side open.","Apply 230 V between LV phase r and neutral; read r–n, y–n, b–n.","Repeat with y and b.","Compare the patterns: a faulty limb shows clearly unequal sharing."]},
  {h:"Investigating a failed DT",s:["Note what happened: trip, fuse blown, smoke, oil thrown out, lightning, overload complaints.","Inspect: oil level and colour, bushing flashover, LT connections and cable lugs burnt, LA condition, earthing, DO fuse ratings used.","Test IR, ratio, winding resistance, magnetising current; these locate HV/LV/turn faults.","Write the probable cause: overload (no LT protection), LT side short, lightning with poor earth/LA, low oil/moisture, loose LT connections."]}],
 notes:[["trap","Failed DTs often trace back to the LT side: overloaded or unprotected LT distribution, loose lugs, or a wire wrapped on the DB instead of proper fuses."],
  ["tip","Ratio 44 is a good number to remember: 11 kV ÷ 250 V phase voltage (433/√3)."],
  ["trap","Never charge a DT with the tap switch between positions; check the locking pin."]],
 rec:["Nameplate: kVA, make, Sl no, year, vector group, impedance %, tap range","IR values with temperature","Ratio per tap per phase","Winding resistance per phase with temperature","Oil BDV","Earth pit values"],
 quiz:[
  {q:"Expected ratio (per phase TTR) for an 11 kV / 433 V Dyn11 DT at normal tap?",o:["25.4","44.0","11.0","76.2"],a:1,e:"11000 ÷ (433/√3 = 250) ≈ 44.0."},
  {q:"In a magnetising current test, phase Y reads 9 mA and R and B read 12 mA each. That is…",o:["A shorted turn on Y","Normal for a 3-limb core","A broken strand on R and B","Wrong tap"],a:1,e:"The middle limb's magnetic path is shorter, so it draws less current."},
  {q:"Winding resistance R–Y 3.10 Ω, Y–B 3.12 Ω, B–R 3.55 Ω. Most likely?",o:["All fine","Fault involving phase B or R (loose joint or tap contact on the B–R path)","Moisture","Wrong vector group"],a:1,e:"One pair about 14% higher points to a high-resistance joint or contact in that path."},
  {q:"Oil BDV of a DT in service reads 24 kV. Action?",o:["Nothing","Filter (dry) or replace the oil before further service","Raise the tap","Increase the fuse rating"],a:1,e:"Low BDV means moisture or particles; filter or replace."}]},

{id:"ptr",g:"Transformers",t:"Power transformer (PTR) testing — 33/11 kV",
 lead:"A PTR (e.g., 3.15, 5, 10 MVA, 33/11 kV, Dyn11, with OLTC) gets the DT tests plus a deeper set: tan delta, SFRA, OLTC checks, protection devices and stability of differential/REF protection. Results are compared with the factory test report and kept as the fingerprint for its whole life.",
 when:["On receipt at site (transport check)","Before commissioning","After a through fault, Buchholz trip or differential trip","Periodic condition monitoring (oil, DGA, tan δ)"],
 kit:["ir5","ttr","wrm","tand","sfra","bdv","pis","rtk","mm"],
 tests:[
  {n:"Receipt checks",w:"Damage in transport is common and hidden.",h:"Check the impact (shock) recorder, N₂ pressure/oil level, bushings, radiators, accessories list.",p:"Impact readings within the maker's limit (often below 3 g); positive gas pressure; no leaks."},
  {n:"IR and PI",w:"Moisture in a large winding.",h:"5 kV: HV–E, LV–E, HV–LV, plus core–earth (500 V/1 kV, core earthing link removed).",p:"33 kV winding ≥ 500 MΩ at 30 °C; PI ≥ 1.5 (≥ 2 good); core–earth typically ≥ 100 MΩ (one earth point only)."},
  {n:"Ratio at all OLTC taps",w:"Correct turns at every step.",h:"TTR, each phase, every tap.",p:"Within ±0.5% of nameplate; even steps."},
  {n:"Winding resistance at all taps",w:"OLTC contacts and joints; continuity while changing tap.",h:"Measure HV at every tap (current on, step through); LV phases.",p:"Phases within about 2%; smooth tap-to-tap steps; no current interruption when tapping."},
  {n:"Magnetising current and magnetic balance",w:"Core/winding faults.",h:"Low-voltage 3-ph on HV; per-phase currents; balance as for DTs.",p:"Pattern matches factory: two similar outers, lower middle."},
  {n:"Short-circuit impedance (%Z)",w:"Winding movement after through faults; paralleling.",h:"Apply 3-ph 415 V to HV with LV shorted; measure current; compute %Z.",p:"Close to nameplate (within a few percent of the factory value)."},
  {n:"Tan delta and capacitance",w:"Ageing and moisture in insulation.",h:"10 kV, winding combinations (CHL, CHG, CLG) and condenser bushings (C1).",p:"Winding tan δ ≤ 0.5% at 20 °C for new; bushings ≤ 0.5% and capacitance within ±5% of nameplate; rising trend = concern."},
  {n:"SFRA",w:"Core or winding movement (transport, faults).",h:"Sweep each winding end-to-end; compare with the factory curve.",p:"Curves overlay the fingerprint; shifts in mid frequencies indicate winding deformation."},
  {n:"OLTC checks",w:"OLTCs are the most failure-prone part.",h:"Manual and electrical operation over the full range, limit switches, step-by-step, out-of-step (for parallel), RTCC/AVR, counter, oil BDV in the diverter.",p:"Operates smoothly end to end; limits stop it; indication matches."},
  {n:"Protection devices",w:"Buchholz, PRV, OTI, WTI, MOG, OSR trip and alarm the breaker.",h:"Air injection for Buchholz, contact simulation for PRV/OSR, oil-bath calibration for OTI/WTI, alarm/trip to the breaker.",p:"Each device gives the right alarm/trip on the panel and trips the right breaker(s)."},
  {n:"Differential and REF stability",w:"Wrong CT polarity or ratio makes the relay trip on load or through-faults.",h:"Primary injection through the CTs (or check spill on first load).",p:"Spill current near zero for through current; operates for internal (in-zone) simulation."},
  {n:"Oil tests and DGA",w:"Insulation condition and incipient faults.",h:"BDV, moisture (ppm), acidity, IFT, resistivity, tan δ; DGA in a lab.",p:"Before charging BDV ≥ 50–60 kV after filtration (check spec); moisture low (≤ ~20–25 ppm for new filled 33 kV units); DGA as baseline."}],
 proc:[
  {h:"Order of pre-commissioning tests",s:["Receipt checks and internal inspection if required by the maker.","Oil filtration till BDV/moisture are within spec; vacuum filling as per the maker.","IR/PI, core–earth, ratio, vector group, winding resistance, magnetising current, magnetic balance, %Z.","Tan δ of windings and bushings; SFRA (keep the curves).","OLTC operation; cooling (fans) and control wiring; protection device checks.","CT tests (bushing CTs, neutral CT); differential/REF stability by primary injection.","Settings applied; trip checks from every device to the HV and LV breakers.","Charge on no load, watch inrush, Buchholz, sound; keep for a few hours; then load in steps."]},
  {h:"Buchholz relay check",s:["Close the isolating valve towards the conservator if required.","Inject air through the test cock slowly: the upper float operates → ALARM on the panel.","Inject more air: the lower float/flap operates → TRIP (both breakers open).","Release air through the vent; reset; confirm no air remains before charging."]}],
 notes:[["trap","A 'healthy' magnetising current test is meaningless if done after a DC test; residual magnetism from winding resistance testing distorts it. Do magnetising/SFRA before winding resistance, or demagnetise."],
  ["tip","The first test results of a new PTR are its fingerprint. Keep them safely; every later test is compared with them."],
  ["trap","Differential relays need the right CT ratio and vector compensation (Dyn11) set in the relay; a missed setting trips the PTR on the first load."]],
 rec:["Full test report per test, factory vs site values","Settings of OTI/WTI alarm/trip, Buchholz, PRV","OLTC counter reading at commissioning","Oil test and DGA baseline"],
 quiz:[
  {q:"Air injected into the Buchholz gives an alarm but more air gives a trip. Which float trips?",o:["Upper","Lower (surge/flap)","Both alarm only","Neither; Buchholz only alarms"],a:1,e:"Upper float = gas accumulation alarm; lower float/flap = trip."},
  {q:"Why test SFRA before winding resistance?",o:["SFRA needs a hot winding","DC from winding resistance magnetises the core and distorts low-frequency results","It doesn't matter","SFRA damages the OLTC"],a:1,e:"Residual magnetism affects SFRA and magnetising tests."},
  {q:"Bushing C1 capacitance has risen 12% since commissioning. This suggests…",o:["Normal ageing","Shorted condenser layers; plan replacement","Wrong test voltage","Oil level is high"],a:1,e:"A rising capacitance means layers of the condenser core are shorting."},
  {q:"Core–earth IR is 0.2 MΩ. What does that suggest?",o:["Healthy","A second (unintended) core earth or contamination","Wrong tap","Normal for 33 kV"],a:1,e:"The core should be earthed at one point only; a low reading suggests another path."}]},

{id:"oil",g:"Transformers",t:"Transformer oil: BDV, moisture, acidity and DGA",
 lead:"Oil is both insulation and coolant. Its condition tells you about the paper insulation and any developing fault inside the tank. Most of these tests are quick at site (BDV) or need a lab sample (moisture, acidity, DGA).",
 when:["Before first charging","After filtration","Annually for PTRs (more often if trending bad)","After a Buchholz alarm or trip (gas and oil sample)"],
 kit:["bdv"],
 tests:[
  {n:"BDV (breakdown voltage)",w:"Water and particles.",h:"Clean dry cell, 2.5 mm gap, fill without bubbles, rest a few minutes, raise at 2 kV/s; 6 breakdowns with stirring and rest between; average.",p:"Common targets for ≤ 72.5 kV equipment: new/filtered oil before charging ≥ 50–60 kV; in service ≥ 40 kV good, below ~30 kV filter/replace. Check the current IS 1866 table and spec."},
  {n:"Water content (ppm)",w:"Moisture in oil (and paper).",h:"Karl Fischer titration in a lab; sample in a dry sealed bottle.",p:"Low and stable; new filled 33 kV units commonly ≤ 20–25 ppm; in service a few tens of ppm max depending on voltage class."},
  {n:"Acidity (neutralisation value)",w:"Oil ageing (oxidation) that attacks paper.",h:"Lab titration, mg KOH/g.",p:"New oil about 0.03; in service rising towards 0.2–0.3 means regenerate or replace."},
  {n:"IFT, resistivity, tan δ of oil",w:"Polar contamination and ageing.",h:"Lab.",p:"Trend; sharp drops in IFT/resistivity or rise in tan δ mean contamination/ageing."},
  {n:"DGA (dissolved gas analysis)",w:"Early warning of internal faults.",h:"Syringe sample from the bottom valve, lab gas chromatograph.",p:"Interpret with IEC 60599 ratios / Duval triangle and trends. H₂ = partial discharge, C₂H₂ = arcing, C₂H₄ = overheating of oil, CO/CO₂ = paper overheating."}],
 proc:[{h:"Taking a good oil sample",fig:"bdv",s:["Use a clean, dry glass bottle rinsed with the same oil.","Flush the drain valve first (throw away about a litre).","Fill slowly along the bottle wall, no bubbles, leave a little space; cap at once.","Label: equipment, date, oil temperature, weather. Sample on a dry day.","For DGA use a gas-tight syringe and avoid air bubbles."]}],
 notes:[["trap","Testing a cold, wet morning sample from a dirty valve condemns good oil. Flush the valve and keep the cell clean and dry."],["tip","Acetylene (C₂H₂) in DGA, even a few ppm, is serious: it needs arcing temperatures."]],
 rec:["BDV (6 readings and average), oil temperature, appearance","Lab results with sampling date"],
 quiz:[
  {q:"Gap in the standard BDV cell?",o:["1 mm","2.5 mm","4 mm","10 mm"],a:1,e:"IEC 60156 / IS 6792 use a 2.5 mm gap."},
  {q:"Which gas points to arcing inside a transformer?",o:["Hydrogen","Acetylene (C₂H₂)","Carbon dioxide","Nitrogen"],a:1,e:"Acetylene forms only at very high temperatures (arcs)."},
  {q:"Rising acidity in oil mainly harms…",o:["Bushings","Paper insulation (accelerates ageing)","The tap changer motor","Radiators"],a:1,e:"Acids attack cellulose insulation."}]},

{id:"tpd",g:"Transformers",t:"Transformer protection devices",
 lead:"Mechanical and thermal devices on the transformer protect it where electrical relays can't see the fault. T&C checks that each gives the right alarm and trip.",
 when:["Commissioning","Annual maintenance","After any alarm or trip from the device"],
 kit:["mm","ir1"],
 tests:[
  {n:"Buchholz relay (63)",w:"Gas from slow faults (alarm); oil surge from serious faults (trip).",h:"Air injection test; check floats, contacts, wiring IR.",p:"Alarm and trip on the panel, correct breakers trip."},
  {n:"PRV / PRD",w:"Relieves a sudden pressure rise; trips the breaker.",h:"Operate the micro-switch by hand; check trip.",p:"Trips both breakers; flag resets."},
  {n:"OTI (oil temperature, 26) and WTI (winding temperature, 49)",w:"Overheating alarm/trip and fan control.",h:"Calibrate the sensing bulb in a hot oil bath against a standard thermometer; check alarm, trip and fan contacts.",p:"Indication within a few °C; typical ONAN settings: OTI alarm ~85 °C, trip ~95 °C; WTI alarm ~95 °C, trip ~105 °C (use approved settings)."},
  {n:"MOG (magnetic oil level gauge)",w:"Low oil alarm.",h:"Check pointer movement and the low-level contact.",p:"Low-level alarm on the panel."},
  {n:"OSR (OLTC oil surge relay)",w:"Faults in the diverter compartment.",h:"Operate the test lever; check trip.",p:"Trips the breakers."},
  {n:"Silica gel breather",w:"Keeps moisture out.",h:"Check colour (blue/orange when dry, pink/green when wet) and the oil seal cup.",p:"Less than about two-thirds changed colour; replace/reactivate otherwise."}],
 notes:[["trap","A Buchholz alarm that keeps coming back is not a 'nuisance': take a gas sample and a DGA sample before resetting."]],
 rec:["Device settings and test results; date of silica gel change"],
 quiz:[
  {q:"WTI measures winding temperature how?",o:["A sensor inside the winding","Oil temperature plus a heater fed from a CT (thermal image)","Infrared","Resistance of the winding on load"],a:1,e:"The heater coil adds the winding-to-oil gradient in proportion to load current."},
  {q:"Silica gel has turned fully pink. Action?",o:["Ignore","Replace/reactivate and check the oil cup","Top up oil","Increase the fan speed"],a:1,e:"Saturated gel no longer stops moisture."}]},

/* ===================== SWITCHGEAR ===================== */
{id:"vcb",g:"Switchgear",t:"VCB testing (11 kV and 33 kV)",
 lead:"A vacuum circuit breaker must close and open fast, on all three poles together, with low contact resistance, a sound vacuum, and coils that work at low DC voltage. These tests prove each of those.",
 when:["Commissioning","After a T&C report of mal-operation or failure to trip","After a set number of fault operations","Periodic maintenance (annual / per maker)"],
 kit:["ir5","dlro","bta","hv","mm","rtk"],
 tests:[
  {n:"IR",w:"Insulation of poles, insulators and across open contacts.",h:"5 kV: each pole to earth (closed), phase-to-phase, and across open contacts. 500 V on control wiring.",p:"Typically ≥ 1,000 MΩ (often GΩ) on primary; control wiring ≥ 2 MΩ (new ≥ 10 MΩ)."},
  {n:"Contact resistance (CRM/DLRO)",w:"Worn or poorly closed contacts heat up on load.",h:"Breaker closed; 100 A (or more) DC across each pole, 4-wire.",p:"Per maker; typically a few tens of µΩ (often ≤ 40–60 µΩ for 11/33 kV VCBs). Poles should be close to each other."},
  {n:"Operating times",w:"Fault clearing depends on speed; unequal poles cause stress.",h:"Breaker timer on each pole's main contact; trip and close commands from the timer.",p:"Per maker; typical close ≤ 60–80 ms, open ≤ 40–60 ms; pole discrepancy ≤ about 3 ms (open) and 5 ms (close)."},
  {n:"Minimum operating voltage of coils",w:"Breaker must trip even with a weak battery.",h:"Variable DC to trip/close coil; find lowest voltage that operates.",p:"Close reliably at 85% of rated DC, trip at 70% (IEC 62271); must not trip below about 30%."},
  {n:"Vacuum integrity",w:"A bottle that has lost vacuum can't interrupt current.",h:"Power-frequency HV across open contacts at the value in the manual, or a vacuum checker.",p:"No breakdown (current stays within kit limit)."},
  {n:"Mechanism and interlocks",w:"Spring charging, anti-pumping and interlocks prevent dangerous operation.",h:"Charge motor time, manual close/trip, anti-pumping (hold close, give trip: must not re-close), counter, mechanical interlocks.",p:"Spring charges in the stated time (often ≤ 15 s); anti-pumping works; counter advances."},
  {n:"Protection trip",w:"The relay must actually open this breaker.",h:"Inject the relay (or operate its contact) and confirm the breaker trips; check the trip circuit supervision (TCS).",p:"Trips from every protection; TCS alarms when the trip circuit is broken."}],
 proc:[
  {h:"Contact resistance",fig:"crm",s:["Breaker closed, isolated and earthed on both sides (remove one earth if the meter needs it).","Current leads on the outer ends of the pole terminals, potential leads inside them.","Inject 100 A; read µΩ; repeat for each pole.","Compare with maker's value and between poles; high value → clean/replace contacts or check the bottle's contact wear indicator."]},
  {h:"Timing test",fig:"timing",s:["Connect timer channels across each pole's main contacts; connect the timer's trip and close outputs to the breaker's coils.","Close command: record each pole's close time. Trip command: record open times.","Compute pole discrepancy = slowest – fastest.","Do a close-open (CO) operation if required."]}],
 notes:[["trap","Many 'breaker did not trip' cases are a broken trip circuit or a low battery, not the breaker. Check TCS, DC voltage and the trip coil before blaming the mechanism."],
  ["safe","Disconnect PTs and surge arresters on the line side before HV testing across contacts."],
  ["tip","Indian panel lamps: red = breaker closed, green = breaker open, amber = tripped on fault, white = trip circuit healthy (check the local scheme)."]],
 rec:["Contact resistance per pole","Close/open times per pole and discrepancy","Coil minimum operating voltages","Operation counter before and after"],
 quiz:[
  {q:"Contact resistance R 32, Y 35, B 140 µΩ. Most likely?",o:["All fine","Pole B contacts worn or not fully closing","Wrong test current","Low battery"],a:1,e:"One pole four times the others needs maintenance."},
  {q:"Minimum trip voltage must be at or below…",o:["30% of rated DC","70% of rated DC","110% of rated DC","Exactly 100%"],a:1,e:"Breakers must trip at 70% (IEC 62271), so a weak battery still trips them."},
  {q:"Anti-pumping prevents…",o:["Spring overcharging","Repeated close-trip cycling while the close command stays on during a fault","Vacuum loss","Overheating"],a:1,e:"With anti-pumping, one close command gives only one close."},
  {q:"How is a vacuum bottle's integrity checked at site?",o:["Megger at 500 V","Power-frequency HV withstand across open contacts (or vacuum checker)","Contact resistance","Timing test"],a:1,e:"A bottle without vacuum flashes over at the test voltage."}]},

{id:"iso",g:"Switchgear",t:"Isolators, AB switches and GOS",
 lead:"Isolators give a visible break; they are not for breaking load. Tests check that all three blades close fully and together, contacts are tight, and interlocks stop misuse.",
 when:["Commissioning","After a hot-spot is found","Annual maintenance"],
 kit:["dlro","ir5","tc"],
 tests:[
  {n:"Contact resistance",w:"Loose or burnt contacts overheat.",h:"DLRO across each closed pole.",p:"Per maker (tens to a few hundred µΩ); poles similar."},
  {n:"Alignment and simultaneous closing",w:"Partial closing = arcing and hot spots.",h:"Operate slowly; check blade entry, pressure, gap when open.",p:"All three close fully and together; open gap as specified."},
  {n:"Earth switch and interlocks",w:"Prevents closing the earth switch on a live line or the isolator with earth on.",h:"Try the wrong sequence; it must be blocked. Check breaker–isolator interlock.",p:"Interlocks hold."},
  {n:"IR",w:"Support insulators and operating rod.",h:"5 kV to earth.",p:"High (GΩ range on clean porcelain)."},
  {n:"Handle earthing (AB switch)",w:"Operator safety.",h:"Check the flexible earth braid from the handle to the earth pit.",p:"Continuous, low resistance."}],
 notes:[["trap","Never operate an isolator on load. Open the breaker first; close the isolator before the breaker."]],
 rec:["Contact resistance per pole; operating check; interlock check"],
 quiz:[{q:"Correct opening sequence of a feeder?",o:["Isolator then breaker","Breaker then isolator","Either","Earth switch first"],a:1,e:"Breakers break current; isolators only after the breaker is open."},
  {q:"Why is the AB switch handle bonded to earth?",o:["To trip the breaker","So a fault on the rod can't make the handle live for the operator","To reduce contact resistance","For lightning"],a:1,e:"The operator holds the handle; it must stay at earth potential."}]},

{id:"panel",g:"Switchgear",t:"Indoor 11 kV switchgear panels",
 lead:"Indoor panels (incomer, bus coupler, feeders) combine a withdrawable VCB truck, CTs, PTs, relays and meters in one metal-clad cubicle. T&C tests the breaker, the instrument transformers, the wiring, the interlocks and the busbar.",
 when:["Commissioning of a new switchboard","After extension or retrofit","Annual maintenance"],
 kit:["ir5","dlro","bta","rtk","pis","hv","mm"],
 tests:[
  {n:"Busbar IR and HV withstand",w:"Proves the busbar and joints after site assembly.",h:"IR before and after; power-frequency test at the site value in the maker's manual (a percentage of factory test).",p:"No breakdown; IR the same before and after."},
  {n:"Bus joint resistance",w:"Site-assembled joints can be loose.",h:"DLRO across each joint.",p:"Low and similar for similar joints."},
  {n:"VCB truck tests",w:"As for any VCB.",h:"See the VCB section; also check racking in Service/Test/Isolated positions.",p:"Mechanism, timings, CRM within limits."},
  {n:"Interlocks and shutters",w:"Operator safety in metal-clad gear.",h:"Try to rack with the breaker closed, open doors live, close the earth switch on a live cable — all must be blocked. Shutters close when the truck is withdrawn.",p:"All interlocks block wrong operations."},
  {n:"CTs, PTs, relays and meters",w:"Correct ratios, polarities and settings.",h:"CT and PT tests, secondary injection, primary injection on CT chain, meter checks.",p:"See those sections."},
  {n:"Control wiring",w:"Wrong wiring = wrong trip or no trip.",h:"Point-to-point check against the schematic; IR of DC/AC circuits at 500 V; functional checks of every indication and alarm.",p:"Matches drawing; IR OK; all functions work."},
  {n:"Space heater and panel earthing",w:"Prevents condensation tracking; safety.",h:"Check heater, thermostat; earth bus continuity to the station earth.",p:"Working; earth bus connected at both ends."}],
 notes:[["tip","Test position lets you close/trip the breaker with control power while the main contacts are disconnected — use it for scheme checks."]],
 rec:["Busbar test; interlock checklist; panel-wise test reports"],
 quiz:[{q:"In which truck position can you test closing and tripping without connecting the busbar?",o:["Service","Test","Isolated","Earthed"],a:1,e:"Test position: secondary plugs connected, primary isolated."},
  {q:"Why do panels have space heaters?",o:["To warm the operator","To stop condensation that causes tracking and flashover","To heat the oil","To dry the battery"],a:1,e:"Condensation on insulation surfaces leads to tracking."}]},

{id:"fuse",g:"Switchgear",t:"Fuses: DO, HG, HRC and LT protection",
 lead:"Fuses protect DTs and spurs cheaply, but only if the right element is used. T&C checks ratings, holders and coordination; a wrong (oversized or bypassed) fuse is a common cause of DT failure.",
 when:["Commissioning a DT","After repeated fuse blowing","During DT failure investigation"],
 kit:["mm","tc"],
 tests:[
  {n:"DO fuse element rating",w:"Must blow on a DT internal fault but not on inrush or normal overload.",h:"Use the maker's/APDCL chart for each kVA; typically a few times the HV full-load current. HV FL current = kVA ÷ (√3 × 11) A.",p:"Element as per the chart; never a plain wire or a higher rating."},
  {n:"Fuse holder and contacts",w:"Burnt holders give poor contact and drop-out.",h:"Visual, operation, thermography on load.",p:"Clean contacts, correct drop-out."},
  {n:"HG fuse (horn gap)",w:"Older DT protection.",h:"Check gap and fuse wire size per chart.",p:"As per chart."},
  {n:"LT side protection",w:"Most DT failures start on the LT side.",h:"LT DB: MCCB/HRC fuse ratings coordinated with DT full load (LT FL current ≈ 1.39 × kVA at 415 V).",p:"Correctly rated; no bypassed fuses or wires wound round the fuse base."}],
 notes:[["trap","A blown DO fuse 'solved' by fitting thicker wire hides a fault and lets it destroy the DT next time. Find why it blew."],
  ["tip","Quick numbers: HV full-load current of a 100 kVA DT ≈ 100 ÷ (1.732 × 11) ≈ 5.25 A; LT full load ≈ 139 A."]],
 rec:["Fuse ratings found and fitted; reason for blowing"],
 quiz:[{q:"LT full-load current of a 63 kVA DT at 415 V is about…",o:["35 A","88 A","152 A","250 A"],a:1,e:"63 × 1.39 ≈ 88 A (63000 ÷ (1.732 × 415))."},
  {q:"A DO fuse blows repeatedly. Correct response?",o:["Fit a heavier element","Find the fault (LT short, overload, DT internal) before re-fusing","Bypass it","Replace the DO set"],a:1,e:"The fuse is doing its job; find the cause."}]},

/* ===================== CTs and PTs ===================== */
{id:"ctout",g:"CTs and PTs",t:"Outdoor CT testing (33 kV)",
 lead:"Outdoor 33 kV CTs (oil-filled, multi-core) feed metering, overcurrent and differential relays. Each core has its own class: 0.2S/0.5 for metering, 5P for protection, PS for differential/REF. Tests check every core separately.",
 when:["Commissioning","After a protection mal-operation","Replacement","Periodic: oil level, tan δ (condition)"],
 kit:["ir5","cta","pis","tand","mm"],
 tests:[
  {n:"IR",w:"Insulation primary–earth and of each secondary.",h:"5 kV primary to earth (secondaries shorted & earthed); 500 V/1 kV each secondary to earth and between cores.",p:"Primary in GΩ range; secondaries ≥ 50 MΩ typical."},
  {n:"Ratio",w:"Wrong ratio = wrong metering/protection.",h:"Primary injection with ammeter on secondary, or CT analyser. Check every core and every tap (S1–S2, S1–S3).",p:"Within class: 0.2S/0.5 metering core error a fraction of a percent; 5P core ±1% at rated current."},
  {n:"Polarity",w:"Reversed CTs reverse meters and make differential/REF trip.",h:"Flick (kick) test: battery on P1(+)–P2, analog DC meter on S1(+)–S2; or the analyser's polarity reading.",p:"Meter kicks forward on switch-on (P1 and S1 same polarity)."},
  {n:"Knee-point voltage and excitation",w:"Protection CTs must not saturate during faults.",h:"Primary open; apply rising AC on the secondary; record V and I to plot the curve; find the knee.",p:"Measured Vk ≥ specified Vk; magnetising current at Vk (or Vk/2) ≤ specified."},
  {n:"Secondary winding resistance (RCT)",w:"Needed for PS-class and relay calculations.",h:"Winding resistance meter or DLRO-type kit.",p:"≤ specified RCT."},
  {n:"Burden",w:"Too much burden makes metering CTs inaccurate and protection CTs saturate.",h:"Inject rated current into the connected loop; measure voltage; VA = V × I.",p:"Connected burden ≤ rated burden."},
  {n:"Tan δ and capacitance",w:"Oil/paper insulation of 33 kV CTs.",h:"At 10 kV via the test tap.",p:"Low and stable (≤ about 0.5–0.7% typical); rising trend → plan replacement."}],
 proc:[
  {h:"Polarity (flick) test",fig:"ctpol",s:["CT isolated; primary disconnected from the line.","Connect a 1.5–9 V battery through a push switch: + to P1, – to P2.","Analog DC milliammeter or multimeter (needle) on the secondary: + to S1, – to S2.","Press the switch: the needle kicks positive → polarity correct. On release it kicks back.","Repeat for each core."]},
  {h:"Knee-point test",fig:"knee",s:["Primary open circuit; other cores shorted.","Variac (via step-up if needed) on S1–S2 with a voltmeter across and an ammeter in series.","Raise voltage in steps, record V and I, first demagnetise by raising to saturation and slowly lowering to zero.","Knee point (IEC): the voltage where a 10% rise in voltage needs a 50% rise in current.","Bring the voltage down slowly to zero to leave the core demagnetised."]}],
 notes:[["safe","Never leave a CT secondary open with primary current flowing. Unused cores are shorted and earthed."],
  ["trap","The secondary star point of a CT set must be earthed at one place only (usually in the panel). Two earths create circulating currents and wrong relay operation."],
  ["tip","Name plate code: 400-200/1-1-1 A, 0.5/5P20/PS — ratio choices, number of cores, and class of each core."]],
 rec:["Ratio, polarity, knee point and excitation curve per core","IR, burden, RCT, tan δ"],
 quiz:[
  {q:"Which CT core class is used for transformer differential protection?",o:["0.2S","0.5","PS (or 5P per scheme)","1.0"],a:2,e:"Differential/REF commonly use PS class cores defined by Vk, RCT and Iex."},
  {q:"In a flick test, P1 is +ve from the battery and the meter on S1/S2 kicks negative. Means?",o:["Polarity correct","Polarity reversed (or meter leads swapped)","Open secondary","Wrong ratio"],a:1,e:"Correct polarity gives a forward kick on switch-on."},
  {q:"The IEC knee point is where…",o:["Current doubles","10% more voltage needs 50% more current","Voltage reaches 100 V","Current is 1 A"],a:1,e:"That's the standard knee-point definition."}]},

{id:"ctin",g:"CTs and PTs",t:"Indoor CT testing (11 kV panels, CBCT)",
 lead:"Indoor CTs are resin-cast, mounted in the 11 kV panel's cable or breaker chamber, often with two cores (metering and protection). Core balance CTs (CBCT) around all three cable cores detect sensitive earth faults.",
 when:["Commissioning of panels","After mal-operation","Retrofits"],
 kit:["ir1","cta","pis","mm"],
 tests:[
  {n:"IR",w:"Insulation of resin body and secondaries.",h:"Primary to earth (5 kV), secondaries at 500 V.",p:"High (GΩ primary); secondaries ≥ 50 MΩ."},
  {n:"Ratio and polarity",w:"As for outdoor CTs.",h:"Primary injection through the panel CT up to the relay/meter terminals checks the whole chain at once.",p:"Relay and meter display the injected current correctly; direction correct."},
  {n:"Knee point (protection core)",w:"Saturation during faults.",h:"Secondary excitation as for outdoor CTs.",p:"≥ specified."},
  {n:"CBCT test",w:"Sensitive E/F must see earth faults but not balanced load.",h:"Pass a single test conductor through the CBCT and inject; the cable screen earth lead must pass back through the CBCT.",p:"Relay picks up at its setting; balanced 3-phase current gives no output."}],
 notes:[["trap","Cable screen earth wires of a CBCT must be brought back through the CBCT before earthing, or sheath currents cause wrong E/F trips."]],
 rec:["Primary injection results to each relay/meter"],
 quiz:[{q:"What does a CBCT measure?",o:["Phase current","Residual (earth fault) current of all three cores together","Voltage","Temperature"],a:1,e:"All three cores pass through; only the unbalance (earth fault) current is seen."},
  {q:"Best single test to prove an indoor CT chain to the relay?",o:["IR","Primary injection up to the relay","Tan δ","Flick test"],a:1,e:"It checks ratio, polarity and wiring together."}]},

{id:"pt",g:"CTs and PTs",t:"PT / VT testing",
 lead:"Voltage transformers (11000/√3 : 110/√3, 33000/√3 : 110/√3) feed meters, voltage relays and directional relays. The tests: insulation, ratio, polarity, secondary voltages, fuses and burden.",
 when:["Commissioning","PT fuse failure alarms","Metering complaints"],
 kit:["ir5","ttr","mm"],
 tests:[
  {n:"IR",w:"Insulation.",h:"5 kV primary to earth with the primary neutral/earth end lifted only if the design allows; 500 V on secondaries.",p:"GΩ range primary; ≥ 50 MΩ secondaries."},
  {n:"Ratio and polarity",w:"Metering and protection accuracy.",h:"TTR, or apply a known LV (e.g., 230 V) on the primary and measure secondary.",p:"Within class (0.2/0.5 metering, 3P protection)."},
  {n:"Secondary voltages and phase sequence",w:"Final proof after charging.",h:"Measure L–L (≈110 V) and L–N (≈63.5 V); phase-sequence meter; open-delta (residual) voltage near zero on a healthy system.",p:"Balanced; RYB sequence; residual voltage only a few volts."},
  {n:"HV and LV fuses",w:"Blown PT fuses stop metering (under-billing) and voltage protection.",h:"Continuity and rating; check fuse-fail alarm.",p:"Correct ratings; alarm works."},
  {n:"Burden",w:"Excess burden lowers accuracy.",h:"Measure the secondary current at rated voltage; VA = V × I.",p:"≤ rated burden."}],
 notes:[["safe","Never short a PT secondary — the opposite of a CT. PT secondaries are fused and must not be shorted."],
  ["trap","An HT consumer's meter with one PT fuse blown records only about two-thirds of the energy. PT fuse failure is a classic metering loss."]],
 rec:["Ratio, polarity, secondary voltages, fuse ratings"],
 quiz:[{q:"Which must never be shorted?",o:["CT secondary","PT secondary","Earth bus","Neutral"],a:1,e:"A shorted PT secondary is a dead short on the PT."},
  {q:"Secondary L–N voltage of a 11000/√3 : 110/√3 PT?",o:["110 V","63.5 V","230 V","11 V"],a:1,e:"110/√3 ≈ 63.5 V."}]},

{id:"ctpt",g:"CTs and PTs",t:"CT-PT metering unit (HT consumers)",
 lead:"A CT-PT unit is a combined oil-filled tank with metering CTs and PTs, used to meter 11 kV/33 kV consumers. Its accuracy decides the bill, so ratio, polarity, wiring and sealing are checked carefully.",
 when:["New HT connection","Load enhancement (CT ratio change)","Meter complaints, theft investigation","Periodic site testing"],
 kit:["ir5","cta","rss","mm","cmri"],
 tests:[
  {n:"IR and oil",w:"Insulation of the unit.",h:"5 kV primary to earth; 500 V secondaries; check oil level and leaks.",p:"High IR; no leaks."},
  {n:"CT ratio and polarity",w:"Billing accuracy.",h:"CT analyser or primary injection.",p:"Within 0.5S/0.2S class at the tested points."},
  {n:"PT ratio and polarity",w:"Billing accuracy.",h:"TTR or applied voltage.",p:"Within class."},
  {n:"Secondary wiring to meter",w:"Wrong phase pairing = wrong billing.",h:"Check each CT pairs with its own PT phase; test terminal block (TTB) wired; check sealing points.",p:"Phasors correct on the meter display; forward kW in every element."},
  {n:"Multiplying factor (MF)",w:"Billing uses it.",h:"MF = (CT ratio × PT ratio) ÷ (meter's rated CT × PT ratio).",p:"Recorded and matches the billing system."}],
 notes:[["tip","Example: CT 30/5 A and PT 11000/110 V on a meter rated -/5 A and 110 V: MF = (30/5 × 11000/110) ÷ (5/5 × 110/110) = 600."]],
 rec:["CT/PT ratios, MF, seal numbers on the unit, TTB, meter and box"],
 quiz:[{q:"CT 50/5 A, PT 11000/110 V, meter -/5 A, 110 V. MF?",o:["10","100","1,000","110"],a:2,e:"(50/5) × (11000/110) = 10 × 100 = 1,000."},
  {q:"What is the test terminal block (TTB) for?",o:["Earthing","Testing/replacing the meter without disconnecting supply, shorting CTs safely","Fusing PTs","Mounting the meter"],a:1,e:"It lets you short CTs and isolate PTs at a sealed point."}]},

/* ===================== SURGE & EARTHING ===================== */
{id:"la",g:"Surge and earthing",t:"Lightning (surge) arresters",
 lead:"Metal-oxide (ZnO) gapless arresters protect DTs, PTRs, cable ends and lines. They fail by slowly conducting more leakage until they burst. Testing tracks leakage and insulation, and checks the earth they depend on.",
 when:["Commissioning","Before monsoon","After a lightning-related failure","Periodic leakage monitoring for substation arresters"],
 kit:["ir5","lac","et","tc"],
 tests:[
  {n:"IR",w:"Moisture ingress, cracked housing.",h:"5 kV between line terminal and earth terminal (arrester disconnected from line).",p:"High (typically GΩ range); compare with similar arresters and earlier readings."},
  {n:"Leakage current (total and resistive)",w:"Degradation of ZnO blocks.",h:"In service, with a leakage current tester (3rd harmonic resistive current method) or the monitor/surge counter's mA meter.",p:"Compare with baseline and other phases; a rising resistive current means replace."},
  {n:"Surge counter",w:"Number of operations.",h:"Read and record.",p:"Count trend; a counter stuck after storms may be faulty."},
  {n:"Earthing",w:"An LA is only as good as its earth.",h:"Shortest straight lead to its own pit (connected to the main earth); measure resistance.",p:"Low (commonly ≤ 1–2 Ω for substation LA earths; as low as practical for DT LAs)."},
  {n:"Distribution LA visual",w:"Disconnector shows a failed arrester.",h:"Check the ground-lead disconnector: dropped = failed arrester.",p:"Disconnector intact, housing clean."}],
 notes:[["trap","A long, looping LA earth lead adds inductance and voltage during a surge; it makes the LA almost useless. Keep it short and straight."],
  ["tip","Ratings: 11 kV distribution class 9 kV, 5 kA; 33 kV station class 30 kV, 10 kA (check spec)."]],
 rec:["IR, leakage readings with date and weather, counter readings, earth value"],
 quiz:[{q:"Distribution LA's ground-lead disconnector has dropped. Meaning?",o:["Normal after a storm","The arrester has failed; replace it","The earth is good","The DT is overloaded"],a:1,e:"The disconnector separates a failed arrester so the line can stay in service."},
  {q:"Which reading best shows ageing of a ZnO arrester in service?",o:["Total leakage only","Resistive (3rd harmonic) leakage trend","Contact resistance","Ratio"],a:1,e:"Capacitive current dominates the total; the resistive part shows degradation."}]},

{id:"earthing",g:"Surge and earthing",t:"Earthing: pits, mats, step and touch",
 lead:"Earthing keeps people safe and lets protection see earth faults. T&C measures pit and mat resistance, soil resistivity for design, and the continuity of every equipment earth.",
 when:["New substation, DT or line","Pre-monsoon and post-monsoon checks","After an electric accident (mandatory investigation)"],
 kit:["et","dlro","mm"],
 tests:[
  {n:"Earth resistance (fall-of-potential)",w:"Resistance of a pit or the whole mat.",h:"3-pole tester: E on the electrode (lead disconnected), current spike C far away, potential spike P at 62% of the E–C distance; also at 52% and 72% to confirm.",p:"Typical targets: 33/11 kV substation mat ≤ 1–2 Ω (RDSS specs often ≤ 2 Ω), DT earths as per spec (commonly ≤ 5 Ω per pit), LA pits as low as practical."},
  {n:"Clamp-on test",w:"Quick check without disconnecting in multi-earthed systems.",h:"Clamp tester around the earth lead.",p:"Use for trend; not valid for a single isolated pit."},
  {n:"Soil resistivity (Wenner)",w:"Design of new earthing.",h:"4 spikes in a line, equal spacing a; ρ = 2πaR.",p:"Used to size the mat/electrodes."},
  {n:"Continuity of equipment earths",w:"Every tank, frame, structure and fence must be bonded.",h:"Low-resistance continuity between the item and the earth mat/riser.",p:"Low (fractions of an ohm)."},
  {n:"Step and touch potential",w:"Safety of people during faults (substations).",h:"Calculated (IEEE 80) or measured with injection.",p:"Below tolerable limits for the fault current and clearing time."}],
 proc:[{h:"Fall-of-potential test on a pit",fig:"earth",s:["Disconnect the earth lead at the test link so you measure only this pit.","Drive C at 5–10× the electrode length (e.g., 25–40 m for a 3 m pipe), in moist soil.","Drive P in line at 62% of the E–C distance.","Read; move P to 52% and 72%; readings should be close. If not, move C farther.","Reconnect the lead. Record soil condition (dry/wet)."]}],
 notes:[["trap","Measuring a pit with the system earth still connected gives the parallel value of all earths — it looks good but tells you nothing about this pit."],["tip","Test in the dry season for the worst case."]],
 rec:["Pit-wise values, date, soil condition, method"],
 quiz:[{q:"P spike position in the fall-of-potential method?",o:["10% of E–C","62% of E–C","Beyond C","At the pit"],a:1,e:"The 62% rule gives the true resistance for a hemispherical electrode model."},
  {q:"Why disconnect the earth lead before testing a pit?",o:["Safety only","Otherwise you measure all parallel earths together","The tester needs AC","To dry the pit"],a:1,e:"Parallel paths make a bad pit look good."}]},

/* ===================== PROTECTION ===================== */
{id:"relays",g:"Protection",t:"Protection relays and settings",
 lead:"Relays watch currents and voltages and trip breakers on faults. A 33/11 kV substation mainly uses overcurrent (50/51), earth fault (50N/51N), transformer differential (87T), restricted earth fault (64R/REF), and transformer devices, with a lockout relay (86) and trip circuit supervision (95).",
 when:["Commissioning","Setting changes after network changes","After mal-operation or failure to operate"],
 kit:["rtk","mm"],
 tests:[
  {n:"Device numbers to know",w:"Read schemes and relay flags.",h:"50/51 phase O/C (instantaneous/IDMT), 50N/51N earth fault, 87T differential, 64R REF, 86 master trip/lockout, 95 or 74 trip circuit supervision, 27 under-voltage, 59 over-voltage, 81 under-frequency (load shedding), 67 directional, 63 Buchholz, 26 OTI, 49 WTI/thermal, 30 annunciator.",p:"—"},
  {n:"IDMT curve (IEC normal inverse)",w:"Gives slower trips for small faults and faster for big ones, allowing grading.",h:"t = TMS × 0.14 ÷ ((I/Is)^0.02 − 1). Other curves: very inverse (13.5/(M−1)), extremely inverse (80/(M²−1)).",p:"—"},
  {n:"Grading",w:"The relay nearest the fault must trip first.",h:"Upstream relay set slower by a grading margin at the maximum fault current seen by both.",p:"Margin about 0.3–0.4 s for electromechanical, 0.2–0.3 s for numerical relays."},
  {n:"Typical setting approach (11 kV feeder)",w:"A starting point; final settings must be approved.",h:"O/C pickup above maximum load (often 100–125% of CT rating or load); E/F pickup 10–20% of CT; TMS chosen for grading; highset to clear close-in faults fast.",p:"No trips on load or cold-load pickup; clears faults selectively."}],
 proc:[{h:"Worked example: IDMT time",s:["11 kV feeder, CT 400/1 A, O/C pickup Is = 400 A (1.0 A secondary), TMS 0.1, IEC normal inverse.","Fault current 4,000 A → M = I/Is = 10.","t = 0.1 × 0.14 ÷ (10^0.02 − 1) = 0.1 × 0.14 ÷ 0.0471 ≈ 0.297 s.","If the 11 kV incomer sees the same 4,000 A, set its TMS so it operates at about 0.6 s (grading margin ~0.3 s)."]}],
 notes:[["tip","Numerical relays store events and disturbance records with fault currents and times. Download them after every significant trip."],["trap","Setting E/F too sensitive on rural feeders with unbalanced single-phase loads causes nuisance trips; too insensitive misses high-resistance faults."]],
 rec:["Relay settings register: relay, CT ratio, settings, approval reference, date applied"],
 quiz:[{q:"What does device 86 do?",o:["Measures frequency","Lockout/master trip: trips and holds breakers until reset","Earth fault detection","Supervises the trip circuit"],a:1,e:"86 is the hand-reset lockout relay."},
  {q:"IEC NI, TMS 0.1, M = 10. Operating time?",o:["0.1 s","0.3 s","1.0 s","3.0 s"],a:1,e:"0.14 ÷ (10^0.02 − 1) ≈ 2.97; × 0.1 ≈ 0.30 s."},
  {q:"Which protection is set to stay stable for faults outside the transformer?",o:["Overcurrent","Differential (87T) / REF","Under-frequency","Buchholz"],a:1,e:"Unit protections only operate for faults inside their zone."}]},

{id:"inject",g:"Protection",t:"Secondary injection: testing relays",
 lead:"Secondary injection feeds test currents and voltages straight into the relay's CT/PT inputs (CT secondaries shorted and isolated at the TTB) to prove pickup, timing, logic and trip outputs.",
 when:["Commissioning","After any setting change","Periodic (typically annual)","After mal-operation"],
 kit:["rtk","mm"],
 tests:[
  {n:"Pickup and drop-off",w:"Relay starts at its setting.",h:"Raise current slowly till the start contact/LED operates; reduce till it resets.",p:"Pickup within the relay's tolerance of the setting (IDMT elements commonly between 1.05 and 1.3 × Is per relay manual); drop-off ratio as stated."},
  {n:"Timing at multiples",w:"Matches the curve.",h:"Inject 2×, 5×, 10× setting; timer stops on the trip contact.",p:"Within the stated tolerance (e.g., ±5% or ±30–40 ms)."},
  {n:"Highset (instantaneous)",w:"Fast clearing of close faults.",h:"Inject just above and just below the highset.",p:"Operates above, not below; time ≤ the setting (+ relay time)."},
  {n:"Differential: slope and harmonic restraint",w:"Stability for through-faults and inrush.",h:"Inject on both sides to check the bias characteristic; inject 2nd harmonic to check inrush blocking.",p:"Operates/restrains per the characteristic; blocks at the set % of 2nd harmonic (often 15–20%)."},
  {n:"Trip and scheme",w:"The relay's contact must trip the breaker and give the right indication.",h:"Inject with the breaker in Test/Service (as planned) and confirm trip, flags, annunciation, events.",p:"Breaker trips; correct alarm and records."}],
 proc:[{h:"Secondary injection on an O/C relay",fig:"sec",s:["Short the CT secondaries and isolate them from the relay at the TTB (so CTs stay shorted and the kit feeds only the relay).","Connect the kit current outputs to the relay current terminals; connect the relay trip contact to the kit's timer input.","Check pickup, then timing at 2×, 5× and 10× Is, phase by phase, then E/F.","Restore links exactly; remove the shorting at the TTB only after the relay circuit is reconnected; check no CT is left open."]}],
 notes:[["trap","The most dangerous step is restoring the TTB links. Check every link with a tong tester on first load (current in every phase at the relay)."]],
 rec:["Settings, pickup, timings at each multiple, trip check results"],
 quiz:[{q:"During secondary injection, the CTs must be…",o:["Open","Shorted at the TTB and isolated from the relay","Connected to the kit","Removed"],a:1,e:"CTs stay shorted; the kit feeds the relay side only."},
  {q:"Why inject 2nd harmonic into a differential relay?",o:["To check its CT ratio","To check inrush restraint (it must block)","To check pickup","To heat the relay"],a:1,e:"Magnetising inrush is rich in 2nd harmonic."}]},

{id:"primary",g:"Protection",t:"Primary injection and stability tests",
 lead:"Primary injection pushes real current through the CT primaries, proving ratio, polarity and every wire up to the relay and meter in one go. It's the best way to catch a reversed or wrongly paired CT before charging.",
 when:["Commissioning","After any CT or wiring change"],
 kit:["pis","mm"],
 tests:[
  {n:"Ratio and wiring",w:"Every CT reaches the right relay/meter terminals.",h:"Inject through one phase's CT primary; read current at relay/meter; repeat each phase.",p:"Relay/meter show injected current ÷ CT ratio on the right phase."},
  {n:"Polarity and differential stability",w:"Reversed CT → differential trips on load.",h:"Inject through CTs on both sides of the zone as a 'through' current (e.g., short on LV side and inject from HV side at low voltage).",p:"Differential spill/operate current near zero; bias current shows the through current."},
  {n:"Earth fault / REF stability",w:"Residual connection correct.",h:"Inject phase-to-neutral through phase CT and neutral CT in through-fault direction.",p:"REF/E-F stable for external faults; operates for simulated internal fault."}],
 proc:[{h:"Primary injection on a feeder CT",fig:"prim",s:["Isolate and earth; open the circuit so the injector loop goes only through the CT primary.","Connect the injector leads across the CT primary (or loop through the panel bushings with a shorting link).","Inject 10–20% of the CT rating; read the relay/meter current and the injector ammeter.","Repeat for each phase and the residual path; record."]}],
 notes:[["tip","On a new PTR, a low-voltage 3-phase supply (415 V) applied to the HV with the LV shorted gives through current on both sides for a quick stability check."]],
 rec:["Injected current, readings at each relay/meter, phase, polarity"],
 quiz:[{q:"What does primary injection prove that secondary injection doesn't?",o:["Relay curve","CT ratio, polarity and wiring up to the relay","Battery health","Breaker timing"],a:1,e:"Secondary injection starts at the relay; primary includes the CTs and wiring."}]},

{id:"trip",g:"Protection",t:"Trip and fault analysis",
 lead:"Every trip is evidence. Reading relay flags and records correctly tells O&M where to look and tells T&C whether the protection did its job.",
 when:["After each feeder or PTR trip","Repeated trips on the same feeder","DT and PTR failures"],
 kit:["cmri","mm"],
 tests:[
  {n:"Read the relay",w:"Which element, which phase, how much current.",h:"Flags/LEDs, event list, fault current, time stamps, disturbance record.",p:"—"},
  {n:"Classify",w:"Guides the patrol.",h:"Highset/instantaneous O/C → close-in heavy fault; IDMT O/C → distant fault or overload; E/F → conductor to earth (tree, broken insulator, fallen wire); both PTR protections (Buchholz/differential) → internal transformer fault.",p:"—"},
  {n:"Was the operation right?",w:"Mal-operation needs correction.",h:"Compare fault current and time with the settings and curves; check upstream/downstream grading.",p:"Correct relay operated in the expected time."}],
 notes:[["safe","After a differential or Buchholz trip, do not re-charge the PTR without tests (IR, ratio, winding resistance, oil/DGA, gas analysis)."],
  ["tip","A feeder that trips on E/F every rainy morning and holds on re-close usually has a cracked pin insulator or tree contact; look for flashover marks."]],
 rec:["Trip log: time, relay, element, phase, current, action, cause found"],
 quiz:[{q:"PTR tripped on differential and Buchholz together. Next step?",o:["Re-close after 5 minutes","Do not charge; test the transformer and analyse gas/oil","Raise the differential setting","Bypass Buchholz"],a:1,e:"Two independent internal-fault protections operating together strongly suggest an internal fault."}]},

/* ===================== DC & CONTROL ===================== */
{id:"cr",g:"DC and control",t:"C&R panels and control wiring",
 lead:"The control and relay (C&R) panel holds relays, meters, control switches, annunciators and their wiring. Most commissioning faults are wiring faults, so the checks are systematic and drawing-based.",
 when:["Commissioning","After modifications","After unexplained trips"],
 kit:["ir1","mm","rtk"],
 tests:[
  {n:"Point-to-point wiring check",w:"Wiring must match the approved schematic.",h:"Ferrule by ferrule with the drawing; mark up changes.",p:"No mismatches; as-built drawing updated."},
  {n:"IR of control circuits",w:"Damaged insulation causes DC earth faults.",h:"500 V on CT, PT, DC and AC circuits (electronic relays disconnected).",p:"≥ 2 MΩ (new wiring usually ≥ 10 MΩ)."},
  {n:"DC earth fault check",w:"A single earth on DC is harmless; a second one causes false trips.",h:"Measure +ve to earth and –ve to earth; or the earth-fault relay on the charger.",p:"About half the battery voltage each side (e.g., ±55 V on 110 V)."},
  {n:"Functional checks",w:"Every control and alarm must work.",h:"Close/trip from panel and local, every protection trip, annunciator windows, lamps, interlocks, synchronising if any.",p:"All functions correct."},
  {n:"Metering",w:"Panel meters show correct values.",h:"Secondary/primary injection; compare with portable meter on load.",p:"Within class."}],
 notes:[["trap","An unbalanced DC (e.g., +ve 10 V, –ve 100 V to earth) means an earth fault on the +ve side. Find it before a second earth causes a false trip."]],
 rec:["Wiring check sheets, IR values, functional test checklist"],
 quiz:[{q:"110 V DC system: +ve to earth reads 5 V, –ve to earth 105 V. Meaning?",o:["Healthy","Earth fault on the +ve side","Earth fault on the –ve side","Charger off"],a:1,e:"The +ve pole is near earth potential, so it is earthed somewhere."}]},

{id:"battery",g:"DC and control",t:"Station battery bank",
 lead:"The station battery is the last line of defence: when the AC fails, it is the only thing that can trip breakers. Most 33/11 kV substations use 110 V DC (some older ones 30 V or 48 V), with flooded lead-acid, VRLA or Ni-Cd cells.",
 when:["Commissioning","Weekly/monthly cell checks","Annual capacity test (or as per policy)","Before relying on a charger outage"],
 kit:["hyd","mm","bdt"],
 tests:[
  {n:"Cell voltages",w:"Shows charge state and weak cells.",h:"Every cell on float, recorded in the battery register.",p:"Lead-acid float about 2.15–2.25 V/cell; Ni-Cd about 1.40–1.45 V/cell. Cells close to each other."},
  {n:"Specific gravity (flooded lead-acid)",w:"State of charge of each cell.",h:"Hydrometer, temperature-corrected to 27 °C (about 0.0007 per °C).",p:"Fully charged per maker (commonly 1.200–1.240). Cells within about ±0.010 of each other."},
  {n:"Electrolyte level, connections",w:"Low level and loose links cause failure and heat.",h:"Visual; torque check; inter-cell connector resistance with DLRO.",p:"Level between marks (add only distilled/DM water); links tight and low resistance."},
  {n:"Capacity (discharge) test",w:"Proves the battery can supply the load for the rated time.",h:"Fully charge, rest, discharge at the 10-hour rate (C10 ÷ 10 A) till the end voltage (lead-acid 1.75–1.80 V/cell); time × current = capacity.",p:"≥ 80% of rated capacity; below that plan replacement."},
  {n:"Internal resistance (VRLA)",w:"VRLA cells can't be hydrometer-tested.",h:"Cell impedance/conductance tester; trend.",p:"Within about 20–25% of baseline; outliers replaced."}],
 proc:[{h:"Weekly battery check",fig:"batt",s:["Read total float voltage and charger current.","Read each cell voltage (or pilot cells weekly, all cells monthly).","Read specific gravity of pilot cells; temperature.","Check levels, top up with distilled water only, clean and apply petroleum jelly to terminals.","Record in the battery register; investigate any cell 0.05 V or 0.020 SG away from the rest."]}],
 notes:[["safe","Hydrogen: no smoking or sparks; ventilate. Wear goggles, gloves and apron. Keep eyewash water ready."],
  ["trap","Never mix lead-acid and Ni-Cd tools, hydrometers or electrolyte."]],
 rec:["Battery register: date, total V, charger current, cell V, SG, temperature, water added"],
 quiz:[{q:"End voltage for a lead-acid C10 discharge test?",o:["2.20 V/cell","1.75–1.80 V/cell","1.40 V/cell","1.00 V/cell"],a:1,e:"Discharge stops at about 1.75–1.80 V per cell."},
  {q:"Capacity test result 72% of rating. Action?",o:["Fine","Plan replacement (below 80%)","Raise float voltage","Add acid"],a:1,e:"Below 80% capacity the bank is at end of life."},
  {q:"Which water is used to top up flooded cells?",o:["Tap water","Distilled / DM water only","Acid","Rain water"],a:1,e:"Impurities poison the plates."}]},

{id:"charger",g:"DC and control",t:"Battery charger (float-cum-boost)",
 lead:"The float-cum-boost charger (FCBC) feeds the DC load and keeps the battery on float; boost mode recharges a discharged battery. Its alarms are the early warning for DC trouble.",
 when:["Commissioning","Monthly checks","After DC alarms"],
 kit:["mm"],
 tests:[
  {n:"Float and boost voltage",w:"Wrong float voltage ruins batteries (too high: gassing; too low: sulphation).",h:"Measure at the battery terminals.",p:"Lead-acid: float ~2.20–2.25 V/cell, boost ~2.30–2.40 V/cell (× number of cells, e.g., 55 cells). Ni-Cd per maker."},
  {n:"Current limit",w:"Protects the charger and battery.",h:"Load test or read the setting.",p:"As set."},
  {n:"Ripple",w:"AC ripple heats batteries and upsets relays.",h:"AC mV range on the DC output, or scope.",p:"Within spec (often ≤ 2%)."},
  {n:"Alarms",w:"AC fail, charger fail, DC under/over-voltage, earth fault.",h:"Simulate each.",p:"Each gives its alarm locally and on the annunciator."},
  {n:"Auto changeover",w:"Float/boost and duplicate chargers.",h:"Switch off one charger; check the other takes over; check boost-to-float return.",p:"No DC interruption."}],
 notes:[["tip","Float for 55 lead-acid cells at 2.22 V/cell = about 122 V; boost at 2.35 V/cell ≈ 129 V."]],
 rec:["Float/boost settings, ripple, alarm test results"],
 quiz:[{q:"Float voltage for 55 lead-acid cells at 2.2 V/cell?",o:["110 V","121 V","132 V","99 V"],a:1,e:"55 × 2.2 = 121 V."}]},

{id:"aux",g:"DC and control",t:"Station transformer and AC auxiliaries",
 lead:"The station (auxiliary) transformer supplies lighting, battery charger, OLTC and fan motors, and heaters. It is a small DT and is tested like one; the AC distribution board (ACDB) and changeover are checked as well.",
 when:["Commissioning","Annual maintenance"],
 kit:["ir5","ir1","ttr","mm"],
 tests:[
  {n:"Transformer tests",w:"As for a DT.",h:"IR, ratio, winding resistance, BDV, earthing.",p:"As DT section."},
  {n:"ACDB",w:"Correct MCB/MCCB ratings and phase balance.",h:"IR of circuits, ratings, tightness, thermography.",p:"Correct and cool."},
  {n:"Supply changeover",w:"Alternative supply for critical loads.",h:"Simulate loss of main supply.",p:"Changeover works; charger restarts."}],
 rec:["Test report like a DT; ACDB checklist"],
 quiz:[{q:"Which critical DC device depends on the station transformer?",o:["The battery charger","The PTR core","The LA","The CT"],a:0,e:"No AC → charger stops → battery discharges."}]},

/* ===================== CABLES & CAPACITORS ===================== */
{id:"cable",g:"Cables and capacitors",t:"HT cable testing and fault location",
 lead:"11 kV and 33 kV XLPE cables are tested after laying and jointing, and located quickly when they fault. Good terminations and joints matter as much as the cable.",
 when:["After laying and termination (commissioning)","After a fault (locate, repair, re-test)","Periodically on critical cables"],
 kit:["ir5","hv","tdr","mm"],
 tests:[
  {n:"IR",w:"Overall insulation before and after HV test.",h:"5 kV each core to the other cores + screen (earthed), 1 min.",p:"High (hundreds of MΩ to GΩ per length); before and after HV test similar."},
  {n:"HV withstand (VLF or AC)",w:"Proves insulation and accessories.",h:"VLF 0.1 Hz (common for XLPE) or resonant AC at site test levels from the spec/IEEE 400.2/IEC 60502-2. DC testing of XLPE is avoided.",p:"No breakdown for the test duration; leakage stable."},
  {n:"Sheath integrity",w:"Damaged outer sheath lets water in.",h:"DC test between metallic screen/armour and earth (commonly about 4 kV/mm of sheath, max 10 kV, 1 min).",p:"No breakdown."},
  {n:"Phasing / continuity",w:"Correct phase at both ends.",h:"Continuity tester between cores end to end.",p:"R–R, Y–Y, B–B confirmed."},
  {n:"Fault location",w:"Find the fault fast.",h:"IR to classify the fault; TDR (pulse echo) for low-resistance and open faults; surge generator (thumper) with ARM/ICE for high-resistance faults; acoustic/magnetic pin-pointing on the route.",p:"Fault distance found; exact spot pin-pointed."}],
 notes:[["safe","A cable holds charge for a long time after IR/HV tests; discharge and earth all cores for long enough before touching."],["tip","Keep the cable's IR and length from commissioning; after a fault, a TDR trace compared with the healthy trace speeds location."]],
 rec:["Cable details, length, test voltages, IR before/after, HV test results"],
 quiz:[{q:"Why is DC HV testing avoided on XLPE cables?",o:["It's too slow","Space charge can damage XLPE and lead to failures after the test","It's illegal","It doesn't reach the far end"],a:1,e:"VLF or AC tests are preferred for XLPE."},
  {q:"Best first tool for a low-resistance cable fault distance?",o:["Megger","TDR (pulse echo)","Thermal camera","Clamp meter"],a:1,e:"TDR shows the reflection at the fault."}]},

{id:"cap",g:"Cables and capacitors",t:"Capacitor banks",
 lead:"Shunt capacitor banks at substations improve power factor and voltage. They store charge and fail by unit swelling or fuse blowing; testing checks capacitance, insulation, discharge and protection.",
 when:["Commissioning","After unbalance trips","Annual maintenance"],
 kit:["ir5","mm","rtk","tc"],
 tests:[
  {n:"Capacitance of each unit",w:"Element failures change capacitance.",h:"Capacitance meter or current at known voltage.",p:"Within a few percent of nameplate (per IS/maker); units in a phase balanced."},
  {n:"IR terminals–case",w:"Insulation to case.",h:"5 kV / 2.5 kV.",p:"High."},
  {n:"Discharge device",w:"Safety after switch-off.",h:"Check discharge resistors; measure residual voltage after switch-off.",p:"Residual voltage down to a safe level (commonly 50 V) within the specified time (often 5 min)."},
  {n:"Unbalance protection",w:"Detects failed units before cascading failures.",h:"Neutral current/voltage relay injection.",p:"Alarms/trips at set unbalance."}],
 notes:[["safe","Wait at least the discharge time after switch-off, then short and earth every terminal before touching."]],
 rec:["Unit-wise capacitance, IR, protection settings"],
 quiz:[{q:"Before touching a switched-off capacitor bank you must…",o:["Touch it with a glove","Wait the discharge time, then short and earth all terminals","Open the neutral","Check the fuses only"],a:1,e:"Capacitors keep a dangerous charge."}]},

/* ===================== METERS ===================== */
{id:"mbasic",g:"Energy meters",t:"Energy meter basics",
 lead:"Meters are cash registers. T&C/MRT checks accuracy, wiring, multiplying factors and tamper. Standards: IS 13779 (whole-current static meters, class 1.0 and 2.0), IS 14697 (CT/PT-operated meters, class 0.2S/0.5S), IS 16444 (smart meters), IS 15959 (DLMS data exchange), and the CEA (Installation & Operation of Meters) Regulations for accuracy classes, testing and sealing.",
 when:["New meter lots (acceptance/sample testing)","Complaint testing (fast/slow meter)","Periodic site testing","Theft/tamper investigation"],
 kit:["bench","rss","cmri","mm"],
 tests:[
  {n:"Accuracy classes",w:"Choose and judge meters correctly.",h:"Class 1.0: error limit about ±1% over the normal range; 0.5S: ±0.5%; 0.2S: ±0.2%. 'S' classes stay accurate down to 1% of rated current.",p:"LT whole-current consumers: class 1.0 (or as per current CEA rules); CT-operated LT and HT consumers: 0.5S or better; interface/feeder metering 0.2S."},
  {n:"Meter constant and pulses",w:"Site tests count LED pulses.",h:"Meter constant (e.g., 3,200 imp/kWh). Pulses per second = kW × constant ÷ 3600.",p:"Error % = (meter energy − reference energy) ÷ reference energy × 100."},
  {n:"Load points",w:"Errors vary with current and power factor.",h:"Lab tests at low current (5–10% Ib), Ib and Imax, at UPF, 0.5 lag and 0.8 lead.",p:"Within the class limits at each point (IS 13779 table)."},
  {n:"Starting current and creep",w:"Meter must start on small loads and not run with no load.",h:"Starting: apply the starting current (class 1: 0.4% of Ib) and check it registers. Creep: 115% voltage, no current; at most one pulse in the specified time.",p:"Starts; doesn't creep."},
  {n:"Register (dial) test",w:"Display matches pulses.",h:"Run a known energy (e.g., 1 kWh) and read the register advance.",p:"Matches within resolution."}],
 notes:[["tip","Pulse rate example: 2 kW kettle on a 3,200 imp/kWh meter → 2 × 3200 ÷ 3600 ≈ 1.78 pulses per second (about 107 per minute)."],
  ["tip","Testing periodicity, who may test, and how billing is revised after a defective meter follow the CEA metering regulations and the AERC supply code currently in force; check the latest amendments."]],
 rec:["Meter Sl no, make, class, constant, test points, errors, seals"],
 quiz:[{q:"Meter constant 1,600 imp/kWh, load 3 kW. Pulses per minute?",o:["80","48","160","27"],a:0,e:"3 × 1600 ÷ 3600 = 1.33 pulses/s × 60 = 80 per minute."},
  {q:"Reference meter shows 1.000 kWh, consumer meter 1.012 kWh. Error?",o:["−1.2%","+1.2% (meter fast)","+0.12%","No error"],a:1,e:"(1.012 − 1.000) ÷ 1.000 × 100 = +1.2%."},
  {q:"What does the 'S' in 0.5S mean?",o:["Smart","Accurate down to low currents (1% of rated)","Single phase","Sealed"],a:1,e:"S-class meters have tighter limits at low loads."}]},

{id:"m1ph",g:"Energy meters",t:"Single-phase meter testing",
 lead:"Single-phase whole-current meters (e.g., 5–30 A or 10–60 A) are the bulk of consumers. They measure both phase and neutral current to resist tampering. Most complaints are tested in the lab; field checks find wiring and tamper problems.",
 when:["Complaint: fast/slow meter, burnt meter","New connection checks","Theft inspections"],
 kit:["rss","bench","mm","cmri"],
 tests:[
  {n:"Site accuracy with a known load",w:"Quick check in front of the consumer.",h:"Switch off all loads; connect a known resistive load (heater/kettle) or the portable reference; count pulses over a time and compare.",p:"Within class 1.0 limits (allow for test uncertainty)."},
  {n:"Phase vs neutral current",w:"Earth loading or neutral bypass tamper.",h:"Tong tester on phase and neutral at the meter.",p:"Equal (no earth leakage path); meter's display matches the higher one."},
  {n:"Tamper events",w:"Magnet, cover open, earth load, reverse, neutral missing.",h:"Read events on display or with CMRI.",p:"No unexplained events."},
  {n:"Lab test",w:"Final accuracy verdict on complaint.",h:"Test bench at standard load points with the consumer or representative present if required; sealed test report.",p:"Within IS 13779 class limits."}],
 proc:[{h:"Site test with a portable reference meter",fig:"meter",s:["Explain the test to the consumer and note seals.","Reference voltage lead across the meter's supply terminals; reference current clamp on the meter's outgoing phase wire.","Point the pulse scanner at the meter's kWh LED; enter the meter constant.","Run on the consumer's load (or a test load) for enough pulses (e.g., 10–20); read the error.","Record, sign with the consumer; if out of limits, remove under seal for lab test."]}],
 notes:[["trap","A meter reading slow with phase current higher than neutral may not be faulty: check for earth load (part of the load returning through earth)."]],
 rec:["Seal numbers before/after, readings, error, consumer signature"],
 quiz:[{q:"Phase current 8 A, neutral 2 A at a 1-ph meter. Likely?",o:["Faulty meter","Load partly returning through earth (earth loading/tamper) or leakage","Normal","Wrong constant"],a:1,e:"In a healthy installation phase and neutral currents are equal."}]},

{id:"m3ph",g:"Energy meters",t:"Three-phase whole-current meter testing",
 lead:"Three-phase whole-current meters serve loads up to about 20–40 kW (e.g., 10–60 A or 20–100 A). Each phase element must see its own voltage and current in the correct direction.",
 when:["New connection","Complaints","Inspections"],
 kit:["rss","mm","cmri"],
 tests:[
  {n:"Per-phase readings",w:"Find a dead or reversed element.",h:"Meter display of V, I, kW and PF per phase vs tong tester and voltmeter.",p:"All phases forward, values match."},
  {n:"Phase sequence and missing voltage",w:"Missing phase = under-recording.",h:"Phase-sequence meter; check all three voltages present.",p:"RYB; three voltages."},
  {n:"Site accuracy",w:"As for 1-ph.",h:"3-phase portable reference with three clamps.",p:"Within class."},
  {n:"Events and load survey",w:"Tamper history.",h:"CMRI download.",p:"No suspicious events."}],
 notes:[["tip","kW check: P ≈ √3 × V(L-L) × I × PF for balanced loads, or the sum of phase V × I × PF."]],
 rec:["Per-phase V/I/PF, error, events"],
 quiz:[{q:"One phase shows negative kW on a consumer meter (consumer has no generation). Likely?",o:["Normal","Reversed connection on that phase","PT fuse blown","Overload"],a:1,e:"Reversed phase element subtracts energy."}]},

{id:"mlt",g:"Energy meters",t:"LT CT-operated meters (and DT meters)",
 lead:"Above whole-current limits, the meter is fed by LT CTs (e.g., 100/5, 200/5 A, class 0.5) through a test terminal block. DT meters for energy accounting are also CT-operated. Errors here come mainly from CT ratio, polarity and phase pairing.",
 when:["New LT industrial/commercial connection","DT metering installation","Complaints and audits"],
 kit:["rss","cta","mm","cmri"],
 tests:[
  {n:"CT ratio at site",w:"Wrong ratio or MF = wrong bill.",h:"Tong tester on primary bus/cable and on the secondary at the TTB.",p:"Primary ÷ secondary ≈ CT ratio."},
  {n:"Polarity and pairing",w:"Each CT must pair with its own phase voltage, forward.",h:"Meter per-phase kW and PF; phasor diagram on the meter or reference.",p:"All phases forward with sensible PF (e.g., 0.8–0.99 lag)."},
  {n:"Accuracy",w:"Meter + wiring.",h:"Portable reference at the TTB.",p:"Within class."},
  {n:"MF and sealing",w:"Billing.",h:"MF = CT ratio ÷ meter's rated ratio (e.g., 200/5 on a -/5 A meter = 40).",p:"MF recorded; CT box, TTB, meter sealed."}],
 notes:[["trap","Swapped CTs between phases can make PF look odd (e.g., 0.5) while total kWh is low — check phase pairing, not just polarity."]],
 rec:["CT ratio, MF, per-phase readings, seals"],
 quiz:[{q:"LT CTs 200/5 A on a -/5 A meter. MF?",o:["5","40","200","1"],a:1,e:"200 ÷ 5 = 40."}]},

{id:"mht",g:"Energy meters",t:"HT meters (TVM) with CT-PT units",
 lead:"HT consumers are billed through a trivector/static meter (0.5S/0.2S) fed by a CT-PT unit. The meter records kWh, kVAh, kVArh, maximum demand, time-of-day and load survey, plus tamper events like PT miss and CT short.",
 when:["New HT connection and load enhancement","Monthly/periodic reading and checks","Disputes and theft investigation"],
 kit:["rss","cmri","mm","cta"],
 tests:[
  {n:"Voltage and current presence",w:"PT fuse failure or CT short under-records.",h:"Meter display per phase and events (PT miss, CT open/short, current unbalance).",p:"All voltages ~63.5 V L–N (or 110 V L–L for 3-wire); currents balanced with load."},
  {n:"Phasor check",w:"Wiring correct.",h:"Meter's or reference's phasor display.",p:"Correct angles for load PF."},
  {n:"Site accuracy",w:"Billing accuracy.",h:"3-phase portable reference (class 0.05/0.1) at the TTB.",p:"Within 0.5S/0.2S class."},
  {n:"MD and TOD",w:"Demand charges depend on MD.",h:"Check MD integration period, reset date, TOD zones and clock.",p:"As per tariff; clock correct."},
  {n:"Data download",w:"Evidence and billing.",h:"CMRI/optical port download: billing data, load survey, events.",p:"Complete data; no unexplained events."}],
 notes:[["trap","One PT fuse blown on a 3-phase 3-wire HT meter can make it record only about half to two-thirds of the energy depending on wiring; a sudden fall in consumption needs a site visit."]],
 rec:["Meter readings, MF, events summary, seals, test error"],
 quiz:[{q:"HT meter event log shows 'R-phase PT missing' for 10 days. Effect?",o:["None","Under-recording during those days; assess and correct PT fuse","Over-recording","Only MD affected"],a:1,e:"Missing voltage on an element stops it measuring."}]},

{id:"smart",g:"Energy meters",t:"Smart meters",
 lead:"Smart meters (IS 16444) communicate with a head-end system (HES) through RF mesh, cellular or NB-IoT, support prepaid billing, and have a built-in load switch (relay) for remote disconnection and reconnection.",
 when:["Installation and commissioning","Communication failures","Disconnection/reconnection complaints"],
 kit:["cmri","mm","rss"],
 tests:[
  {n:"Communication",w:"No data = no bill/recharge.",h:"Check HES shows the meter, last communication time, signal strength.",p:"Regular data at the set interval."},
  {n:"Load switch",w:"Remote disconnect/reconnect.",h:"Command from HES; verify relay status at site and supply restored.",p:"Operates on command; status reported correctly."},
  {n:"Accuracy and events",w:"As for other static meters.",h:"Reference meter; event log.",p:"Within class; events explained."}],
 notes:[["tip","When a remote reconnection fails, check in order: HES command status, meter communication, relay status on the meter display, then the installation (neutral, MCB)."]],
 rec:["Meter ID, communication status, command history"],
 quiz:[{q:"Remote reconnection command shows 'success' in HES but the consumer has no supply. First site check?",o:["Change the meter","Meter display relay status and the consumer's MCB/neutral","Call the vendor","Raise MD"],a:1,e:"Confirm what the meter reports and the downstream installation before blaming the meter."}]},

{id:"tamper",g:"Energy meters",t:"Tamper and theft detection",
 lead:"T&C/MRT often supports enforcement squads. The job is to find and document tampering so the assessment stands up.",
 when:["Inspections and raids","Abnormal consumption patterns","Meter events flagged"],
 kit:["mm","rss","cmri","tc"],
 tests:[
  {n:"Common methods",w:"Know what to look for.",h:"Direct hooking before the meter; neutral bypass/earth loading; magnet on meter; CT secondary shorting; PT wire cut or fuse removed; reversed CT; tampered seals; meter body opened; remote-controlled devices.",p:"—"},
  {n:"Checks",w:"Evidence.",h:"Compare tong-tester load with meter display; phase vs neutral current; seals vs seal register; event log download; photos and video; witnesses.",p:"Documented findings signed on the spot."},
  {n:"Afterwards",w:"Legal process.",h:"Seize the meter in a sealed bag if needed; joint inspection report; assessment per the Electricity Act 2003 (Section 126 for unauthorised use, Section 135 for theft) and the supply code.",p:"Report complete and defensible."}],
 notes:[["trap","An inspection report without seal numbers, photos and consumer acknowledgement is easily challenged."]],
 rec:["Inspection report, seizure memo, photos, meter data download"],
 quiz:[{q:"Strongest evidence of neutral bypass at a 1-ph meter?",o:["Low bill","Phase current at the meter much higher than neutral current, plus a parallel neutral/earth path found","Old meter","High voltage"],a:1,e:"Measured current mismatch plus the physical path."}]},

{id:"mrt",g:"Energy meters",t:"MRT lab procedures",
 lead:"The meter testing lab tests new meter lots, complaint meters and removed meters on a calibrated test bench. Its reports decide billing revisions, so procedure and traceability matter.",
 when:["Lot acceptance of new meters","Complaint/challenge tests","Removed and seized meters"],
 kit:["bench","rss","cmri"],
 tests:[
  {n:"Bench calibration",w:"Traceability.",h:"Reference standard calibrated by an NABL-accredited lab; certificate in date.",p:"Valid calibration."},
  {n:"Lot sample testing",w:"Accept/reject a supply.",h:"Sample as per the purchase specification/IS sampling plan; run accuracy, starting, creep, dielectric where specified, and tamper features.",p:"Lot accepted only if samples pass."},
  {n:"Complaint test",w:"Fair verdict.",h:"Consumer informed; seals checked and recorded; test at standard points; result signed.",p:"Within class → bill stands; outside → billing revised per regulations."}],
 rec:["Lab register, test reports, calibration certificates"],
 quiz:[{q:"Why must the reference standard be NABL-traceable?",o:["For speed","So test results are legally and technically defensible","For colour","It isn't needed"],a:1,e:"Traceable calibration makes the result defensible."}]},

/* ===================== COMMISSIONING & UPKEEP ===================== */
{id:"comm",g:"Commissioning and upkeep",t:"Commissioning a 33/11 kV substation",
 lead:"Commissioning brings everything together: individual tests, scheme checks, then a careful first charging. The goal is that nothing surprises you when power arrives.",
 when:["New substation or bay","Major augmentation (new PTR)"],
 kit:["ir5","ttr","wrm","dlro","bta","cta","rtk","pis","et","bdv","mm"],
 tests:[
  {n:"Pre-checks",w:"Site ready.",h:"Erection complete per drawing; earthing done and measured; clearances; fencing; fire fighting; documents (SLD, schematics, test certificates, approved settings).",p:"Checklist complete."},
  {n:"Equipment tests",w:"Each item healthy.",h:"PTR, CTs, PTs, LAs, VCBs, isolators, panels, cables, battery, charger, station transformer.",p:"All within limits."},
  {n:"Scheme tests",w:"Everything works together.",h:"Each protection trips the right breakers; alarms and indications; interlocks; primary injection stability; DC supervision.",p:"All verified and signed."},
  {n:"Statutory approval",w:"Required before energising HV installations.",h:"Electrical Inspector's inspection/approval as required under the CEA safety regulations in force; self-certification where permitted.",p:"Approval in hand."},
  {n:"First charging",w:"Controlled energisation.",h:"Charge the 33 kV incoming; then PTR on no load (watch inrush, noise, Buchholz) for a few hours; then 11 kV bus; then feeders one by one; check phase sequence and voltages.",p:"No abnormal sound, smell, heating or alarms."},
  {n:"On load",w:"Final proof.",h:"Load in steps; check differential spill near zero, metering correct, thermography after a few hours/days.",p:"Stable."}],
 notes:[["trap","Before paralleling two PTRs or two sources, check phasing and voltage at the coupling point; vector group and tap positions must match."]],
 rec:["Commissioning report signed by T&C, O&M, contractor; handing-over documents"],
 quiz:[{q:"Why charge a new PTR on no load first?",o:["To save energy","To observe inrush, noise and protection stability without load complications","Because OLTC needs it","It's not needed"],a:1,e:"Problems show up safely without load."}]},

{id:"dtcharge",g:"Commissioning and upkeep",t:"Charging a new DT in the field",
 lead:"Most of your field commissioning will be DTs. A short checklist avoids the classic first-day failures.",
 when:["Every new or replaced DT"],
 kit:["ir5","ir1","ttr","bdv","et","mm"],
 tests:[
  {n:"Before charging",w:"Catch problems while the DT is dead.",h:"IR and ratio (or test certificate verified); oil level and BDV; breather; tap at normal and locked; LAs connected with short earth lead; 3 earth pits measured; DO fuse elements correct; LT DB with correct protection; neutral earthed; all connections tight.",p:"All checked."},
  {n:"Charge on no load",w:"Watch it settle.",h:"LT MCCB open; close DO fuses (phase by phase per practice); listen for a steady hum; wait 10–15 min.",p:"Even hum; no smell, no oil leak."},
  {n:"LT checks",w:"Before connecting consumers.",h:"LT voltages L–L about 415–433 V, L–N about 240–250 V; phase sequence; neutral–earth voltage near zero.",p:"Balanced; correct sequence."},
  {n:"On load",w:"Balanced and protected.",h:"Connect circuits; check phase currents and balance after a day; thermography of LT lugs.",p:"Phases balanced within ~20%; no hot joints."}],
 notes:[["trap","Uneven LT voltage with one phase very high means a broken or loose neutral; disconnect load immediately — appliances will burn."]],
 rec:["DT commissioning sheet with readings and earth values"],
 quiz:[{q:"After charging, LT readings: R–N 300 V, Y–N 180 V, B–N 240 V. Likely?",o:["Normal","Loose/broken neutral","Wrong tap","Overload"],a:1,e:"A floating neutral shifts phase voltages; fix before loading."}]},

{id:"pm",g:"Commissioning and upkeep",t:"Preventive maintenance and thermography",
 lead:"A planned schedule of tests catches most failures early. Thermography on load is the fastest way to find bad joints.",
 when:["Planned schedule (monthly, quarterly, annual)","Before summer peak and monsoon"],
 kit:["tc","ir5","bdv","et","hyd","dlro"],
 tests:[
  {n:"Monthly",w:"Quick health.",h:"Battery cell checks, charger alarms, silica gel, oil levels, visual of yard, thermography of loaded feeders/PTR connections.",p:"Logged."},
  {n:"Quarterly / half-yearly",w:"Deeper checks.",h:"Oil BDV (PTR), relay flags and event reviews, earth pit watering checks, cleaning of insulators in polluted areas.",p:"Logged."},
  {n:"Annual",w:"Full condition.",h:"IR of PTR/VCB/CTs, breaker timing and CRM, relay secondary injection, earth resistance, LA leakage, DGA, battery capacity (as per policy).",p:"Compared with fingerprints."},
  {n:"Thermography grading",w:"Prioritise repairs.",h:"Temperature rise above a similar reference component under similar load.",p:"A common guide: ΔT < 10 °C minor, 10–20 °C plan, 20–40 °C repair soon, > 40 °C repair immediately (adjust for load)."}],
 notes:[["tip","Thermography is meaningful only on load; note the load current with every image."]],
 rec:["Maintenance schedule and history card for each equipment"],
 quiz:[{q:"A jumper clamp is 45 °C hotter than the other phases on similar load. Priority?",o:["Ignore","Repair immediately","Next year","Only paint it"],a:1,e:"Very high ΔT means the joint may fail soon."}]},

{id:"records",g:"Commissioning and upkeep",t:"Records, reports and formats",
 lead:"In T&C, the report is the product. A test not recorded didn't happen; a vague report helps nobody. Good records also let you see trends.",
 when:["Every test, every time"],
 kit:[],
 tests:[
  {n:"Test report",w:"Evidence and history.",h:"Header (equipment, location, rating, Sl no, date, weather/temperature, instruments with calibration), readings in a table, limits, result, remarks, recommendations, signatures.",p:"Complete and legible."},
  {n:"Registers",w:"Running history.",h:"Relay settings register; battery register; earth resistance register; meter testing and seal registers; failure register; equipment history cards.",p:"Up to date."},
  {n:"Defect declaration",w:"Starts repair/replacement and estimates.",h:"Equipment, test results that fail, recommendation (repair/replace), urgency.",p:"Clear enough for an estimate to be made from it."}],
 notes:[["tip","When T&C declares equipment defective, that report is usually the first attachment of the replacement estimate in the BoQ Trainer's VCB and DT examples."]],
 rec:["Keep scanned copies with the equipment ID"],
 quiz:[{q:"Which detail makes a test report defensible?",o:["Nice formatting","Instrument serial number and calibration validity","Colour photos only","Long remarks"],a:1,e:"Traceable instruments make readings credible."}]},

{id:"cheat",g:"Commissioning and upkeep",t:"Pass-mark cheat sheet",
 lead:"The typical values from every section in one place. Always confirm against the maker's manual, the purchase specification and APDCL's current T&C instructions.",
 when:["Quick reference in the field"],
 kit:[],
 cheat:[
  ["Transformer IR (1 min, 30 °C, CBIP guide)","33 kV ≥ 500 MΩ · 11 kV ≥ 400 MΩ"],
  ["DAR / PI","DAR ≥ 1.3 · PI ≥ 1.5 (≥ 2 good)"],
  ["Transformer ratio","±0.5% of nameplate"],
  ["Winding resistance","Phases within ~2%; correct to 75 °C"],
  ["Oil BDV (2.5 mm)","Before charging ≥ 40 kV (DT) / ≥ 50–60 kV (PTR, filtered) · filter below ~30 kV in service"],
  ["Tan δ (winding/bushing)","≤ 0.5% at 20 °C (new); bushing capacitance within ±5%"],
  ["VCB contact resistance","Per maker; typically tens of µΩ; poles similar"],
  ["VCB times","Close ≤ 60–80 ms, open ≤ 40–60 ms (maker); pole discrepancy ≤ ~3 ms open / 5 ms close"],
  ["Coil minimum operation","Close at 85%, trip at 70% of rated DC"],
  ["Control wiring IR (500 V)","≥ 2 MΩ (new ≥ 10 MΩ)"],
  ["CT knee point","Measured Vk ≥ specified; Iex ≤ specified"],
  ["PT secondary","110 V L–L, 63.5 V L–N"],
  ["Earth resistance","33/11 kV SS ≤ 1–2 Ω · DT pits per spec (often ≤ 5 Ω) · LA pits lowest"],
  ["Battery float (lead-acid)","2.15–2.25 V/cell · boost 2.30–2.40 V/cell · end of discharge 1.75–1.80 V/cell"],
  ["Battery capacity","≥ 80% of rated, else replace"],
  ["Meter class limits","1.0 → ±1% · 0.5S → ±0.5% · 0.2S → ±0.2% (normal range)"],
  ["Meter pulses/s","kW × imp/kWh ÷ 3600"],
  ["DT ratio 11 kV/433 V","≈ 44.0 (per phase)"],
  ["Full-load current","HV: kVA ÷ (1.732 × 11) · LT: ≈ 1.39 × kVA"],
  ["IDMT (IEC NI)","t = TMS × 0.14 ÷ (M^0.02 − 1)"],
  ["Thermography ΔT","<10 minor · 10–20 plan · 20–40 soon · >40 now"]],
 quiz:[]}
];
